INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('560', 'politeknik-stmi-jakarta-meraih-piagam-apresiasi-di-bidang-keuangan', 'Politeknik STMI Jakarta Meraih Piagam Apresiasi Di Bidang Keuangan', '<p>&nbsp;</p>\n<p><img fetchpriority=\"high\" fetchpriority=\"high\" decoding=\"async\" class=\"size-large wp-image-561 aligncenter\" src=\"{base_url}wp-content/uploads/2024/03/Politeknik-STMI-Jakarta-Meraih-Piagam-Apresiasi-Di-Bidang-Keuangan-1024x614.jpg\" alt=\"\" width=\"1024\" height=\"614\" srcset=\"{base_url}wp-content/uploads/2024/03/Politeknik-STMI-Jakarta-Meraih-Piagam-Apresiasi-Di-Bidang-Keuangan-1024x614.jpg 1024w, {base_url}wp-content/uploads/2024/03/Politeknik-STMI-Jakarta-Meraih-Piagam-Apresiasi-Di-Bidang-Keuangan-300x180.jpg 300w, {base_url}wp-content/uploads/2024/03/Politeknik-STMI-Jakarta-Meraih-Piagam-Apresiasi-Di-Bidang-Keuangan-768x461.jpg 768w, {base_url}wp-content/uploads/2024/03/Politeknik-STMI-Jakarta-Meraih-Piagam-Apresiasi-Di-Bidang-Keuangan.jpg 1500w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></p>\n<p>Keuangan dan Strategi Pembangunan Budaya Resiko Kementerian Perindustrian Tahun 2024 di Ruang Garuda, Lantai 2 Gedung Kementrian Perindustrian pada Kamis (1/2/2024).</p>\n<p>Acara Kick Off Pengelolaan Keuangan dan Strategi Pembangunan Budaya Resiko Kementerian Perindustrian dihadari oleh Menteri Perindustrian Agus Gumiwang Kartasasmita, Plt. Sekretaris Jenderal Putu Juli Ardika, Inspektur Jenderal M. Rum, Para Pejabat Pimpinan Tinggi Madya, Pejabat Pimpinan Tinggi Pratama, Para Kepala UPT, para Staff Khusus, para Tenaga Ahli, Penasehat Menteri Perindustrian.</p>\n<p>Acara diawalai dengan laporan dari Plt. Sekretaris Jenderal Kementrian Perindustrian, Putu Juli Ardika. “Kementerian Perindustrian adalah Kementerian pertama yang mampu melaksanakan amanah Perpres Nomor 39 Tahun 2023 tentang Manajemen Resiko Pembangunan Nasional” ujarnya.</p>\n<p>M. Rum Selaku Inspektur Jenderal dalam sambutannya memaparkan Tujuan Kementerian Perindustrian Dalam Renstra 2020-2024 “Meningkatnya Peran Sektor Industri Dalam Perekonomian Nasional”.</p>\n<p>Selanjutnya acara penyerahan Piagam Apresiasi di Bidang Keuangan salah satunya Politeknik STMI Jakarta  menerima Piagam Apresiasi di Bidang Keuangan  sebagai perwakilan dari satuan kerja Politeknik dengan Nilai Capaian Kinerja Penerimaan PNBP terbaik di lingkungan Politeknik/Akademi Kominitas diwakilkan langsung oleh Direktur Politeknik STMI Jakarta, Mustofa.</p>\n<p>Dalam acara ini Menteri Perindustrian memberikan sambutan sekaligus melakukan launching Peraturan Menteri Perindustrian Nomor 24 Tahun 2023 tentang Manajemen Resiko Pembangunan di lingkungan Kementerian Perindustrian.</p>\n', '<p>&nbsp; Keuangan dan Strategi Pembangunan Budaya Resiko Kementerian Perindustrian Tahun 2024 di Ruang Garuda, Lantai 2 Gedung Kementrian Perindustrian pada Kamis (1/2/2024). Acara Kick Off Pengelolaan Keuangan dan Strategi Pembangunan Budaya Resiko Kementerian Perindustrian dihadari oleh Menteri Perindustrian Agus Gumiwang…</p>\n', '1', '561', 'publish', '2024-02-01 16:00:21', '2024-03-12 13:07:54', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('568', 'student-exchange-di-nit-kosen-niihama-college-jepang', 'Student Exchange Di NIT (KOSEN) NIIHAMA COLLEGE JEPANG', '<p><img fetchpriority=\"high\" fetchpriority=\"high\" decoding=\"async\" class=\"size-large wp-image-569 aligncenter\" src=\"{base_url}wp-content/uploads/2024/03/Student-Exchange-Di-NIT-KOSEN-NIIHAMA-COLLEGE-JEPANG-1024x614.jpg\" alt=\"\" width=\"1024\" height=\"614\" srcset=\"{base_url}wp-content/uploads/2024/03/Student-Exchange-Di-NIT-KOSEN-NIIHAMA-COLLEGE-JEPANG-1024x614.jpg 1024w, {base_url}wp-content/uploads/2024/03/Student-Exchange-Di-NIT-KOSEN-NIIHAMA-COLLEGE-JEPANG-300x180.jpg 300w, {base_url}wp-content/uploads/2024/03/Student-Exchange-Di-NIT-KOSEN-NIIHAMA-COLLEGE-JEPANG-768x461.jpg 768w, {base_url}wp-content/uploads/2024/03/Student-Exchange-Di-NIT-KOSEN-NIIHAMA-COLLEGE-JEPANG.jpg 1500w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></p>\n<p>Program pertukaran pelajar atau biasa disebut <em>student exchange</em> adalah program dimana siswa dari sekolah menengah atau pendidikan tinggi belajar di luar negeri di salah satu lembaga mitra lembaganya. Program pertukaran pelajar mungkin melibatkan perjalanan internasional, namun tidak mengharuskan pelajar untuk belajar di luar negara asalnya seperti dilansir oleh Wikipedia. Adapun syarat mengikuti pertukaran pelajar atau <em>student exchange</em> diantaranya. Memiliki nilai akademik yang memuaskan. Memiliki prestasi pada bidang tertentu. Memiliki kemampuan berbahasa asing yang dibuktikan dengan <em>score</em> Test Of English as a Foreign Language (TOEFL)</p>\n<p>“Politeknik STMI Jakarta dan NIT (KOSEN) NIIHAMA COLLEGE melaksanakan program pertukaran pelajar. Program pertukaran ini merupakan tindak lanjut dari <em>Memorandum of Understanding (MoU)</em> antara Politeknik STMI Jakarta dengan NIT (KOSEN) NIIHAMA COLLEGE” kata Direktur Politeknik STMI Jakarta, Mustofa (1/3).</p>\n<p>Politeknik STMI Jakarta adalah perguruan tinggi vokasi industri dalam naungan Badan Pengembangan Sumber Daya Manusia Industri (BPSDMI) Kementerian Perindustrian yang memiliki program-program studi terkait otomotif, di antaranya Teknik Industri Otomotif, Sistem Informasi Industri Otomotif, Administrasi Bisnis Otomotif, Teknik Kimia Polimer, dan Teknologi Rekayasa Otomotif.</p>\n<p>Niihama National College of Technology adalah perguruan tinggi teknologi di Niihama, Ehime, Jepang. Didirikan pada tahun 1962, menggabungkan sekolah menengah dan perguruan tinggi menjadi kursus lima tahun. Niihama National College of Technology ini menawarkan program sarjana di bidang Teknik Mesin, Teknik Elektro dan Ilmu Informasi, Teknik Kontrol Elektronik, Kimia Terapan dan Bioteknologi, dan Teknik Material Lingkungan, serta tiga program teknik lanjutan.</p>\n<p><em>“Memorandum of Understanding (MoU)</em> antara Politeknik STMI Jakarta dengan NIT (KOSEN) NIIHAMA COLLEGE diselenggarakan pada acara Wisuda Program Sarjana Terapan dan Pendidikan Vokasi Setara D1 tahun 2022. Sebagai bentuk dari pertukaran pelajar ini, mahasiswa dari Niihama College Jepang berkuliah di Politeknik STMI Jakarta dan mahasiswa Politeknik STMI Jakarta berkuliah di Niihama College Jepang”, lanjut Mustofa.</p>\n<p>Mahasiswa Politeknik STMI Jakarta yang mengikuti <em>Student Exchange</em> terdiri dari 4 mahasiswa dari Program Studi Teknologi Rekayasa Otomotif yaitu, Andi Muhammad Hanif Tjoppo, Muhammad Rizqi Akbar, Reza Melliyanno Putra Aji, Mochamad Adam Hidayat, serta di dampingi langsung oleh Dosen sekaligus Kepala Program Studi Teknologi Rekayasa Otomotif Al Kautsar Permana, MT.</p>\n<p>Direktur Politeknik STMI Jakarta, Mustofa, menjelakan bahwa bentuk implementasi <em>Memorandum of Understanding (MoU)</em> ini dimulai di tahun 2023 dimana satu orang mahasiswa dari Niihama College bernama Rin Okamoto berkuliah di Politeknik STMI Jakarta. Kemudian, ditahun 2024 ini giliran mahasiswa Politeknik STMI Jakarta yang akan berkuliah di Jepang, ujarnya.</p>\n<p>“Satu hal yang menjadi spesial pada kegiatan pertukaran pelajar ke Jepang ini, seluruh rangkaian kegiatan di Jepang disponsori oleh pemerintah Jepang melalui hibah <em>Sakura Science Exchange Program</em>. Hibah ini didapatkan pada bulan Oktober 2023. Proses persiapan keberangkatan berlangsung lancar dimulai dari pembuatan <em>passport</em> mahasiswa, <em>apply visa</em>, hingga penerbitan tiket pesawat, dan akomodasi. Di Jepang, mahasiswa akan berkegiatan selama 6 hari terhitung mulai tanggal 3 – 8 Maret 2024. Mereka akan belajar di bengkel-bengkel kampus Niihama College mengenai material logam dan desain mesin. Kegiatan diakhiri dengan presentasi proyek dan kunjungan ke Pabrik <em>Sumitomo Heavy Industry</em>”, kata Mustofa.</p>\n<p>Direktur, Mustofa dalam penutup laporan Pelepasan Mahasiswa Politeknik STMI Jakarta Dalam rangka Student Exchange di NIT (KOSEN) NIIHAMA COLLEGE “kegiatan pelepasan mahasiswa ke Jepang hari ini menunjukkan eksistensi Politeknik STMI Jakarta secara global. Besar harapan kami, kolaborasi antara Niihama College dengan Politeknik STMI Jakarta dapat terus berlanjut sehingga setiap tahun kegiatan ini dapat diselenggarakan. Lebih luas lagi harapannya Politeknik STMI Jakarta dapat berkolaborasi dengan kampus lainnya, ujarnya.</p>\n', '<p>Program pertukaran pelajar atau biasa disebut student exchange adalah program dimana siswa dari sekolah menengah atau pendidikan tinggi belajar di luar negeri di salah satu lembaga mitra lembaganya. Program pertukaran pelajar mungkin melibatkan perjalanan internasional, namun tidak mengharuskan pelajar untuk belajar di…</p>\n', '1', '569', 'publish', '2024-03-04 16:00:45', '2024-03-12 13:07:20', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('575', 'kunjungan-smk-futuhiyyah-mraggen-demak-ke-politeknik-stmi-jakarta', 'Kunjungan SMK Futuhiyyah Mraggen Demak Ke Politeknik STMI Jakarta', '<p><img fetchpriority=\"high\" fetchpriority=\"high\" decoding=\"async\" class=\"alignnone size-large wp-image-576\" src=\"{base_url}wp-content/uploads/2024/03/Kunjungan-SMK-Futuhiyyah-Mraggen-Demak-Ke-Politeknik-STMI-Jakarta-1024x614.jpg\" alt=\"\" width=\"1024\" height=\"614\" srcset=\"{base_url}wp-content/uploads/2024/03/Kunjungan-SMK-Futuhiyyah-Mraggen-Demak-Ke-Politeknik-STMI-Jakarta-1024x614.jpg 1024w, {base_url}wp-content/uploads/2024/03/Kunjungan-SMK-Futuhiyyah-Mraggen-Demak-Ke-Politeknik-STMI-Jakarta-300x180.jpg 300w, {base_url}wp-content/uploads/2024/03/Kunjungan-SMK-Futuhiyyah-Mraggen-Demak-Ke-Politeknik-STMI-Jakarta-768x461.jpg 768w, {base_url}wp-content/uploads/2024/03/Kunjungan-SMK-Futuhiyyah-Mraggen-Demak-Ke-Politeknik-STMI-Jakarta.jpg 1500w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></p>\n<p>Jakarta, Politeknik STMI Jakarta menerima kunjungan dari SMK Futuhiyyah Mraggen Demak Rabu (7/3), peserta kunjungan terdiri dari 81 siswa, 3 Guru dan Wakil Kepala Sekolah.</p>\n<p>Sekolah Menengah Kejuruan  Futuhiyyah Mranggen Demak yang sering dikenal dengan sebutan SMK Futuhiyyah ( SMKF ) Mranggen   adalah Lembaga  Pendidikan Teknik  Menengah Swasta  dibawah  Yayasan Pondok Pesantren Futuhiyyah,</p>\n<p>SMK yang beralamat di  Jln Suburan Mranggen Kabupaten Demak, Telp.    ( 024 ) 70769019, Faximile ( 024 ) 6773287, E-Mail : smkf@futuhiyyah.net.   SMK   Futuhiyyah  berdiri pada tahun 1998 berdasarkan Rekomendasi Kantor Wilayah Departemen Pendidikan dan Kebudayaan Jawa Tengah  Nomor  : 0847 / 103.08 / MN / 98.</p>\n<p>Program yang dibuka adalah Teknologi dan Industri, jurusan Otomotif, Program Studi Mekanik Otomotif, dan Jurusan Elektronika, program studi Elektronika Komunikasi.  Menyesuaikan dengan  kurikulum Edisi 1999, pada tanggal 12 Oktober 2000, berdasarkan Surat Keputusan Kepala Dinas  Pendidikan dan Kebudayaan  Propinsi Jawa tengah  No. 486 / 103.08 / DIN / 2000, Program Teknologi Industri dikonversi menjadi Program Keahlian Teknik Mesin, Bidang Keahlian Teknik Otomotif, dan Program Keahlian Teknik Elektro menjadi  Bidang Keahlian Teknik Audio-Video.</p>\n<p>Kunjungan SMK Futuhiyyah langsung disambut oleh Plt Direktur Politeknik STMI Jakarta Dr. Mustofa, ST, MT. Dalam sambutannnya Mustofa mengatakan “berharap agar lulusan dari SMK Futuhiyyah Mraggen Demak ada yg masuk Politeknik STMI Jakarta”.</p>\n<p>“Biaya masuk Politeknik STMI Jakarta sangat terjangkau karena Politeknik STMI Jakarta merupakan perguruan tinggi Negeri di naungan Badan Pengembangan Sumber Daya Manusia Industri (BPSDMI) Kementerian Perindustrian, dengan biaya Rp 4.500.000,- tanpa uang gedung dan biaya lainnya”, kata Plt Direktur.</p>\n<p>Politeknik STMI Jakarta memiliki program studi dengan spesialisasi pada indsutri otomotif, di antaranya Teknik Industri Otomotif, Sistem Informasi Industri Otomotif, Administrasi Bisnis Otomotif, Teknik Kimia Polimer, dan Teknologi Rekayasa Otomotif.</p>\n<p>Plt Direktur, Mustofa, menjelaskan bahwa Politeknik STMI Jakarta menyiapkan lulusan yang siap untuk bekerja di industri, Politeknik STMI Jakarta merupakan perguruan tinggi yang tidak besar tapi bukan berarti Politeknik STMI Jakarta terbatas sarana, karena Politeknik STMI Jakarta berbasis kurikulum Pendidikan Sistem Ganda (5-2-1). 5 semester di kampus, 2 semester di industri dan 1 semester melaksanakan proyek tugas akhir.</p>\n<p>“Semoga dalam kunjungan ini siswa-siswa dari SMK Futuhiyyah Mraggen Demak  bisa berminat belajar di Politeknik STMI Jakarta, dan menjadi awal kolaborasi yg berkelanjutan antara Politeknik STMI Jakarta dengan SMK Futuhiyyah Mraggen Demak”, lanjut Mustofa.</p>\n<p>Wakil Kepala Sekolah dari SMK Futuhiyyah Mraggen Demak, menjelaskan “Tujuan pertama kami mengadakan kunjungan untuk mengunjungi PT Laksana di ungaran Semarang, yang ternyata banyak lulusan dari Politeknik STMI Jakarta yang berkerja dan melaksanakan Praktik Kerja Industri (Prakerin), maka dari itu kami langsung melakukan kunjungan ke Politeknik STMI Jakarta”.</p>\n<p>Dalam kunjungan tersebut siswa-siswa dari SMK Futuhiyyah Mraggen Demak juga di jelaskan tentang tata cara Penerimaan Mahasiswa Baru melalui Jarvis.</p>\n<p>Jarvis adalah akronim dari Jalur Penerimaan Vokasi Industri dimana merupakan sistem penerimaan mahasiswa baru yang ada di Kampus/Perguruan Tinggi dibawah Kementerian Perindustrian. Terdapat 3 (tiga) Jalur Jarvis tiap tahunnya, yaitu : Jarvis Prestasi, Jarvis Bersama dan Jarvis Mandiri.</p>\n<p>Ketua Penerimaan Mahasiswa Baru, menjelaskan, “Jarvis Prestasi STMI merupakan jalur Penerimaan Mahasiswa Baru tanpa melalui tes tulis, dimana dalam proses seleksinya menggunakan nilai rapor dan wawancara (dalam menggali potensi, minat dan bakat calon Mahasiswa baru), Jarvis bersama yang pelaksanaannya diselenggarakan secara serentak oleh BPSDMI Kementerian Perindustrian RI (Mei – Juni), Jarvis mandiri yang dilaksanakan yang terdiri dari Jarvis Mandiri Reguler dan Jarvis Mandiri UTBK (sertifikat hasil UTBK).</p>\n<p>Jadwal pelaksanaan Jarvis Politeknik STMI Jakarta Tahun 2024/2025, JARVIS Prestasi (Nilai Raport, Prestasi Sebagai Nilai Tambah) Pendaftaran  dibuka dari 08 Januari sampai 26 Maret 2024 dan seleksi wawacara pada 31 Maret 2024, Jarvis bersama yang pelaksanaannya diselenggarakan secara serentak oleh BPSDMI Kementerian Perindustrian RI (Mei – Juni).</p>\n<p>Jarvis Mandiri Reguler I pendaftaran 8 Januari – 26 Maret 2024, seleksi tulis 30 April 2024, dan seleksi wawancara 04 &#8211; 05 Mei 2024. Jarvis Mandiri UTBK (sertifikat hasil UTBK) Pendaftaran 13 Juni – 17 Juli 2024 dan seleksi wawancara 20 Juli 2024. Jarvis Mandiri Reguler II pendaftaran 13 Juni – 02 Agustus 2024 Seleksi Tulis 06 Agustus 2024 dan seleksi wawancara 10 &#8211; 11 Agustus 2024.</p>\n', '<p>Jakarta, Politeknik STMI Jakarta menerima kunjungan dari SMK Futuhiyyah Mraggen Demak Rabu (7/3), peserta kunjungan terdiri dari 81 siswa, 3 Guru dan Wakil Kepala Sekolah. Sekolah Menengah Kejuruan  Futuhiyyah Mranggen Demak yang sering dikenal dengan sebutan SMK Futuhiyyah ( SMKF…</p>\n', '1', '576', 'publish', '2024-03-07 16:00:01', '2024-03-12 13:07:15', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('586', 'pendampingan-penerapan-aplikasi-srikandi-di-politeknik-stmi-jakarta', 'Pendampingan Penerapan Aplikasi SRIKANDI Di Politeknik STMI Jakarta', '<p><img fetchpriority=\"high\" fetchpriority=\"high\" decoding=\"async\" class=\"alignnone size-large wp-image-587\" src=\"{base_url}wp-content/uploads/2024/03/Pendampingan-Penerapan-Aplikasi-SRIKANDI-Di-Politeknik-STMI-Jakarta-1024x614.jpg\" alt=\"\" width=\"1024\" height=\"614\" srcset=\"{base_url}wp-content/uploads/2024/03/Pendampingan-Penerapan-Aplikasi-SRIKANDI-Di-Politeknik-STMI-Jakarta-1024x614.jpg 1024w, {base_url}wp-content/uploads/2024/03/Pendampingan-Penerapan-Aplikasi-SRIKANDI-Di-Politeknik-STMI-Jakarta-300x180.jpg 300w, {base_url}wp-content/uploads/2024/03/Pendampingan-Penerapan-Aplikasi-SRIKANDI-Di-Politeknik-STMI-Jakarta-768x461.jpg 768w, {base_url}wp-content/uploads/2024/03/Pendampingan-Penerapan-Aplikasi-SRIKANDI-Di-Politeknik-STMI-Jakarta.jpg 1500w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></p>\n<p>Jakarta, Politeknik STMI Jakarta melaksanakan pendampingan penerapan aplikasi Sistem Informasi Kearsipan Dinamis Terintegrasi (SRIKANDI) di Aula Lantai 7 Politeknik STMI Jakarta pada Senin (29/1/2024).</p>\n<p>Dalam acara Pendampingan Penerapan Aplikasi SRIKANDI, Politeknik STMI Jakarta mengundang Setia utama selaku Arsiparis Ahli Utama dan Anna Pragiawati  Arsiparis Ahli Madya Biro Umum Kementerian Perindustrian untuk menjadi pembicara dan pendamping Penerapan Aplikasi SRIKANDI di Politeknik STMI Jakarta.</p>\n<p>Kegiatan ini dibuka oleh Direktur Politeknik STMI Jakarta Mustofa dan diikuti oleh semua tenaga kependidikan (subbaggian umum dan subbagian administrasi akademik, mahasiswa dan kerjasama) serta beberapa perwakilan dari anggota program studi dan anggota Unit yang ada di Politeknik STMI Jakarta.</p>\n<p>Selanjutnya, para narsumber memaparkan Penerapan Aplikasi SRIKANDI dimulai dari Ir. Setia Utama membawakan materi tentang Sistem Pemerintahan Berbasis Elektronik (SPBE)  Bidang Kearsipan Aplikasi SRIKANDI dan  Anna Pragiawati tentang Panduan Penggunaan SRIKANDI serta Pengelolaan Arsip Dinamis &amp; PAE Sesuai Peraturan Menteri No 48  Tahun 2022 tentang Penyelenggaraan Kearsipan.</p>\n', '<p>Jakarta, Politeknik STMI Jakarta melaksanakan pendampingan penerapan aplikasi Sistem Informasi Kearsipan Dinamis Terintegrasi (SRIKANDI) di Aula Lantai 7 Politeknik STMI Jakarta pada Senin (29/1/2024). Dalam acara Pendampingan Penerapan Aplikasi SRIKANDI, Politeknik STMI Jakarta mengundang Setia utama selaku Arsiparis Ahli Utama…</p>\n', '1', '587', 'publish', '2024-01-31 16:00:17', '2024-03-12 13:08:00', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1093', 'pengumuman-libur-perkuliahan', 'Pengumuman Libur Perkuliahan', '<p>Kepada mahasiswa/i Politeknik STMI Jakarta</p>\n<p>Berikut terlampir Pengumuman Libur Perkuliahan Kegiatan Rapat Kerja Dosen dan Karyawan</p>\n<p>Mohon diperhatikan tanggal yang tertera, Terimakasih</p>\n<div class=\'w3eden\'><!-- WPDM Link Template: Default Template -->\n\n<div class=\"link-template-default card mb-2\">\n    <div class=\"card-body\">\n        <div class=\"media\">\n            <div class=\"mr-3 img-48\"><img decoding=\"async\" class=\"wpdm_icon\" alt=\"Icon\"   src=\"https://tro.stmi.ac.id/wp-content/plugins/download-manager/assets/file-type-icons/pdf.svg\" /></div>\n            <div class=\"media-body\">\n                <h3 class=\"package-title\"><a href=\'{base_url}download/pengumuman-libur-perkuliahan\'>Pengumuman Libur Perkuliahan</a></h3>\n                <div class=\"text-muted text-small\"><i class=\"fas fa-copy\"></i> 1 file(s) <i class=\"fas fa-hdd ml-3\"></i> 678 KB</div>\n            </div>\n            <div class=\"ml-3\">\n                <a class=\'wpdm-download-link download-on-click btn btn-primary btn-sm\' rel=\'nofollow\' href=\'#\' data-downloadurl=\"{base_url}download/pengumuman-libur-perkuliahan?wpdmdl=1100&amp;refresh=6aa7b38f2a68a1789375375\">Download</a>\n            </div>\n        </div>\n    </div>\n</div>\n\n</div>\n', '<p>Kepada mahasiswa/i Politeknik STMI Jakarta Berikut terlampir Pengumuman Libur Perkuliahan Kegiatan Rapat Kerja Dosen dan Karyawan Mohon diperhatikan tanggal yang tertera, Terimakasih</p>\n', '1', '779', 'publish', '2024-02-22 16:00:27', '2024-03-12 13:22:53', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1109', 'seleksi-prakerin-oleh-pt-mada-wikri-tunggal-di-politeknik-stmi-jakarta', 'Seleksi Prakerin Oleh PT Mada Wikri Tunggal Di Politeknik STMI Jakarta', '<p>Jakarta, Politeknik STMI Jakarta melalui unit STMI Karir bekerja sama dengan PT Mada Wikri Tunggal mengadakan seleksi Prakerin (Praktek Kerja Industri) untuk mahasiswa angkatan 2021 Selasa (6/2/2024).</p>\n<p>Prakerin (Praktek Kerja Industri) adalah kegiatan pendidikan, pelatihan dan pembelajaran yang dilaksanakan di dunia usaha atau dunia industri yang relevan dengan dengan kompetensi (kemampuan) mahasiswa sesuai bidangnya.</p>\n<p>Seleksi yang diadakan oleh PT Mada Wikri Tunggal terbuka untuk semua Program Studi yang ada di Politeknik STMI Jakarta, yaitu program studi Administrasi Bisnis Otomotif, Teknik Kimia Polimer, Teknik Industri Otomotif, Teknik Kimia Polimer, Sistem Informasi Industri Otomotid dan Teknologi Rekayasa Otomotif.</p>\n<p>Dari 75 mahasiswa angkatan 2021 yang mendaftar dan mengikuti tahap psikotest serta interview HR, akan diseleksi menjadi 40 mahasiswa sesuai dengan kebutuhan PT Mada Wikri Tunggal.</p>\n<p>Nantinya dari 40 mahasiswa yang lulus dari psikotest dan interview HR akan di tempatkan di beberapa Plant PT Mada Wikri tunggal diantaranya Plant I Pasir Sari 12 mahasiswa, Plant II Bandung 6 mahasiswa, Plant III Pasir Gombong 15 mahasiswa dan Plant IV Jababeka 7 mahasiswa.</p>\n', '<p>Jakarta, Politeknik STMI Jakarta melalui unit STMI Karir bekerja sama dengan PT Mada Wikri Tunggal mengadakan seleksi Prakerin (Praktek Kerja Industri) untuk mahasiswa angkatan 2021 Selasa (6/2/2024). Prakerin (Praktek Kerja Industri) adalah kegiatan pendidikan, pelatihan dan pembelajaran yang dilaksanakan di…</p>\n', '1', '779', 'publish', '2024-02-07 16:00:17', '2024-03-12 13:07:32', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1112', 'pengumuman-pembayaran-bpp-tahun-2024', 'Pengumuman Pembayaran BPP Tahun 2024', '<p>Kepada mahasiswa/i Politeknik STMI Jakarta</p>\n<p>Berikut terlampir Pengumuman Pembayaran BPP Tahun 2024</p>\n<p>Mohon diperhatikan pengumuman dan tanggal yang tertera, terimakasih</p>\n<div class=\'w3eden\'><!-- WPDM Link Template: Default Template -->\n\n<div class=\"link-template-default card mb-2\">\n    <div class=\"card-body\">\n        <div class=\"media\">\n            <div class=\"mr-3 img-48\"><img decoding=\"async\" class=\"wpdm_icon\" alt=\"Icon\"   src=\"https://tro.stmi.ac.id/wp-content/plugins/download-manager/assets/file-type-icons/pdf.svg\" /></div>\n            <div class=\"media-body\">\n                <h3 class=\"package-title\"><a href=\'{base_url}download/pengumuman-pembayaran-bpp-tahun-2024\'>Pengumuman Pembayaran BPP Tahun 2024</a></h3>\n                <div class=\"text-muted text-small\"><i class=\"fas fa-copy\"></i> 1 file(s) <i class=\"fas fa-hdd ml-3\"></i> 273 KB</div>\n            </div>\n            <div class=\"ml-3\">\n                <a class=\'wpdm-download-link download-on-click btn btn-primary btn-sm\' rel=\'nofollow\' href=\'#\' data-downloadurl=\"{base_url}download/pengumuman-pembayaran-bpp-tahun-2024?wpdmdl=1111&amp;refresh=6aa7b38fa02121789375375\">Download</a>\n            </div>\n        </div>\n    </div>\n</div>\n\n</div>\n', '<p>Kepada mahasiswa/i Politeknik STMI Jakarta Berikut terlampir Pengumuman Pembayaran BPP Tahun 2024 Mohon diperhatikan pengumuman dan tanggal yang tertera, terimakasih</p>\n', '1', '779', 'publish', '2024-02-05 16:03:05', '2024-03-12 13:27:28', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1115', 'campus-hiring-pt-mayora-di-politeknik-stmi-jakarta', 'Campus Hiring PT Mayora Di Politeknik STMI Jakarta', '<p>Jakarta, Politeknik STMI Jakarta melalui unit STMI Karir bekerja sama dengan Mayora Group mengadakan Campus Hiring di Aula Lantai 7 Gedung A Politeknik STMI Jakarta pada hari Kamis (1/2/2024)</p>\n<p>Kebutuhan akan SDM yang handal dan profesional menjadi hal krusial karena pesatnya perkembangan industri. Dalam rangka  memenuhi kebutuhan SDM di bidang industri Mayora Grup mengadakan Campus Hiring terhadap lulusan Politeknik STMI Jakarta khususnya Prodi Teknik Industri Otomotif. Unit STMI Karir dibawah koordinasi Pembantu Direktur III Bidang Kemahasiswaan dan Kerjasama memiliki fungsi salah satunya untuk memfasilitasi para calon alumni dan alumni dalam memasuki dunia kerja.</p>\n<p>Kegiatan  Campus Hiring ini dibuka oleh Pembantu Direktur III Bidang Mahasiswa dan Kerjasama, Muhamad Agus. “Semoga kegiatan Campus Hiring ini berjalan dengan lancar dan Mayora Grup mendapatkan kandidat yang sesuai dengan kebutuhan perusahaan perusahaan, Politeknik STMI Jakarta akan selalu terbuka untuk kegiatan Campus Hiring Selanjutnya” ujarnya.</p>\n<p>Adapun proses rekrutmen ini diawali dengan mengirim CV secara online melalui email HRD Mayora Grup. Kemudian dilanjutkan dengan proses psikotest dan interview HR pada tanggal 1 Februari 2024 di Politeknik STMI Jakarta.</p>\n<p>Turut hadir jajaran HR Mayora Grup dari cabang Cianjur dan cabang Jakarta, yaitu Ridwan Haditio Nugroho selaku Talent  Acquisition Coordinator, Reysinta Kartika selaku Talent Acquisition dan Maria Rosa selaku MDP HR.</p>\n<p>Total Peserta yang mengikuti kegiatan Campus Hiring ini berjumlah 60 peserta, 22 dari internal Politeknik STMI Jakarta dan 38 dari eksternal Politeknik STMI Jakarta.</p>\n', '<p>Jakarta, Politeknik STMI Jakarta melalui unit STMI Karir bekerja sama dengan Mayora Group mengadakan Campus Hiring di Aula Lantai 7 Gedung A Politeknik STMI Jakarta pada hari Kamis (1/2/2024) Kebutuhan akan SDM yang handal dan profesional menjadi hal krusial karena…</p>\n', '1', '779', 'publish', '2024-02-05 16:02:51', '2024-03-12 13:26:40', NULL, NULL);
