INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1154', 'kegiatan-uji-kompetensi-lsp-p1-politeknik-stmi-tahun-2023', 'Kegiatan Uji Kompetensi LSP-P1 Politeknik STMI Tahun 2023', '<p><a href=\"{base_url}wp-content/uploads/2024/03/Kegiatan-Uji-Kompetensi-LSP-P1-Politeknik-STMI-Tahun-2023.jpg\"><img fetchpriority=\"high\" fetchpriority=\"high\" decoding=\"async\" class=\"aligncenter size-full wp-image-1155\" src=\"{base_url}wp-content/uploads/2024/03/Kegiatan-Uji-Kompetensi-LSP-P1-Politeknik-STMI-Tahun-2023.jpg\" alt=\"\" width=\"1024\" height=\"614\" srcset=\"{base_url}wp-content/uploads/2024/03/Kegiatan-Uji-Kompetensi-LSP-P1-Politeknik-STMI-Tahun-2023.jpg 1024w, {base_url}wp-content/uploads/2024/03/Kegiatan-Uji-Kompetensi-LSP-P1-Politeknik-STMI-Tahun-2023-300x180.jpg 300w, {base_url}wp-content/uploads/2024/03/Kegiatan-Uji-Kompetensi-LSP-P1-Politeknik-STMI-Tahun-2023-768x461.jpg 768w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></a></p>\n<p>Alhamdulillah<br />\nKegiatan uji kompetensi LSP-P1 Politeknik STMI tahun 2023 telah selesai di selenggarakan. Kegiatan uji kompetensi 2023 di bagi menjadi 10 gelombang dan dikuti oleh 310 asesi. Kegiatan ini dapat diselenggarakan dalam 5 bulan, dimulai di bulan Maret 2023 dan berakhir di bulan Juli 2023.</p>\n', '<p>Alhamdulillah Kegiatan uji kompetensi LSP-P1 Politeknik STMI tahun 2023 telah selesai di selenggarakan. Kegiatan uji kompetensi 2023 di bagi menjadi 10 gelombang dan dikuti oleh 310 asesi. Kegiatan ini dapat diselenggarakan dalam 5 bulan, dimulai di bulan Maret 2023 dan…</p>\n', '1', '1155', 'publish', '2023-07-31 16:00:48', '2024-03-12 13:08:40', NULL, NULL);
