LL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1169', 'temu-industri-politeknik-stmi-jakarta', 'Temu Industri Politeknik STMI Jakarta', '<p><strong>Membangun Sinergi Pendidikan Dual System untuk Mewujudkan SDM Industri yang Kompeten dan Berdaya Saing Global</strong></p>\n<p>Politeknik STMI Jakarta sebagai salah satu unit pendidikan tinggi vokasi di bidang otomotif yang berada di bawah naungan Badan Pengembangan Sumber Daya Manusia Industri (BPSDMI) Kementerian Perindustrian terus melakukan upaya peningkatan sinergi dan kerjasama dengan industri. Kerjasama dan kolaborasi dengan dunia industri dapat diwujudkan dalam bentuk menyusun kurikulum yang sesuai dengan kebutuhan industri, pemagangan/Prakerin, penempatan lulusan, sertifikasi kompetensi dan evaluasi program.</p>\n<p>Salah satu upaya meningkatkan kolaborasi ini dilakukan dengan mengadakan temu industri di tahun 2023. Acara ini dihadiri oleh 52 industri di sekitar Jabodetabek. Temu Industri ini juga dihadiri oleh Masrokhan sebagai Kepala BPSDMI Kementerian Perindustrian dan Emmy Suryandari yang merupakan Kepala Pusat Pengembangan Pendidikan Vokasi Industri (PPPVI).</p>\n<p><span class=\"fontstyle0\">“Temu Industri ini sejalan dengan upaya Kementerian Perindustrian (Kemenperin) untuk menghasilkan tenaga kerja industri yang memiliki kompetensi melalui kolaborasi dengan berbagai mitra industri. Industri otomotif nasional sendiri mencapai total kapasitas produksi 2,35 juta unit tiap tahun. Kegiatan tersebut menyerap tenaga kerja langsung sampai 38.000 orang. Tercatat penyerapan tenaga kerja di sepanjang rantai nilai industri otomotif, termasuk pada sektor industri kecil dan menengah (IKM) pada bidang komponen juga mampu mencapai lebih dari 1,5 juta tenaga kerja. Oleh karena itu semua lembaga pendidikan vokasi industri dibawah BPSDMI Kemenperin harus dapat menjalin kemitraan yang erat dengan berbagai pihak, dengan tujuan untuk menghasilkan tenaga kerja industri yang siap bekerja, baik untuk kebutuhan dalam negeri maupun di tingkat internasional.” ujar Masrokhan</span></p>\n<p><span class=\"fontstyle0\">Sementara itu, Kepala Pusat PPVI Emmy Suryandari juga menjelaskan tentang pentingnya pendidikan </span><span class=\"fontstyle2\">dual system </span><span class=\"fontstyle0\">untuk mewujudkan SDM Industri Kompeten.</span></p>\n<p><span class=\"fontstyle0\">“Dalam pendidikan </span><span class=\"fontstyle2\">dual system, </span><span class=\"fontstyle0\">peran industri sangat penting agar lulusan memiliki pengalaman kerja yang </span>nyata dan sesuai dengan kebutuhan industri. Kemitraan antara unit pendidikan tinggi vokasi dengan mitra industri penting, termasuk di Politeknik STMI Jakarta, untuk menghadapi tantangan industri di Indonesia dan diperlukan peningkatan kompetensi untuk terus bersaing secara global” ujar Emmy Suryandari</p>\n<p><span class=\"fontstyle0\">Politeknik STMI Jakarta memiliki lima program studi yang berkaitan dengan bidang industri otomotif, yakni program studi Teknik Industri Otomotif (TIO), Sistem Informasi Industri Otomotif (SIIO), Teknik Kimia Polimer (TKP), Administrasi Bisnis Otomotif (ABO), dan Teknologi Rekayasa Otomotif (TRO) yang sudah menerapkan pendidikan </span><span class=\"fontstyle2\">dual system </span><span class=\"fontstyle0\">dengan praktik kerja industri selama satu tahun.</span></p>\n<p><span class=\"fontstyle0\">“Dalam rentang waktu bulan Januari sampai dengan April 2023, Politeknik STMI Jakarta telah bekerja sama dengan 82 perusahaan otomotif dan pendukungnya untuk menempatkan 253 mahasiswa Prakerin (Praktik Kerja Industri) angkatan 2020 di wilayah Jabodetabek, Karawang dan Bandung. Saya sampaikan apresiasi dan penghargaan kepada para pimpinan perusahaan, HR Division, dan para pembimbing di perusahaan. Semoga menguatkan kemitraan antara Politeknik STMI Jakarta dengan industri untuk menyiapkan tenaga kerja industri yang kompeten dan berdaya saing global” jelas Mustofa dalam Laporan Direktur Politeknik STMI Jakarta pada acara temu industri</span></p>\n<p><span class=\"fontstyle0\">Penghargaan diberikan kepada lima mitra industri PT Laksana Tekhnik Makmur, PT Ganding Toolsindo, dan PT Injeksi Plastik oleh BPSDMI Kemenperin kepada industri yang telah berkolaborasi dalam programpraktek kerja industri untuk mewujudkan </span><span class=\"fontstyle2\">dual system </span><span class=\"fontstyle0\">di Politeknik STMI Jakarta.</span></p>\n<p><span class=\"fontstyle0\">Selain itu dilaksanakan juga penandatanganan Memorandum of Understanding (MoU) dengan PT Fuji Technica Indonesia, PT Akebono Brake Astra Indonesia dan Inline Group. Direktur Politeknik STMI Jakarta, Mustofa menyampaikan bahwa kerjasama ini merupakan kolaborasi yang akan memperkuat tri darma perguruan tinggi sekaligus mendorong sinergi untuk menciptakan SDM yang siap kerja.</span></p>\n<p><span class=\"fontstyle0\">Dalam acara temu industri, BPSDMI Kemenperin juga melakukan sosialisasi sistem informasi </span><span class=\"fontstyle2\">Career Development Center </span><span class=\"fontstyle0\">(CDC) yang memiliki fungsi sebagai job portal antara lulusan pendidikan vokasi dibawah BPSDMI dengan mitra industri, menyediakan informasi pelatihan kompetensi dan juga berfungsi untuk melakukan pelacakan alumni (tracer study).</span></p>\n', '<p>Membangun Sinergi Pendidikan Dual System untuk Mewujudkan SDM Industri yang Kompeten dan Berdaya Saing Global Politeknik STMI Jakarta sebagai salah satu unit pendidikan tinggi vokasi di bidang otomotif yang berada di bawah naungan Badan Pengembangan Sumber Daya Manusia Industri (BPSDMI) Kementerian Perindustrian…</p>\n', '1', '779', 'publish', '2023-07-06 16:01:31', '2024-03-12 13:08:56', NULL, NULL);
