INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1636', 'pengumuman-pelaksanaan-swab-antigen-rutin-periode-1-bagi-mahasiswa-politeknik-stmi-jakarta-2022', 'Pengumuman Pelaksanaan SWAB Antigen Rutin Periode 1 Bagi Mahasiswa Politeknik STMI Jakarta 2022', '<p>Kepada Yth. Mahasiswa/i Politeknik STMI Jakarta</p>\n<p>Berikut kami lampirkan informasikan Pelaksanaan SWAB Antigen Rutin Periode 1 Bagi Mahasiswa Politeknik STMI Jakarta Tahun Akademik 2021/2022.</p>\n<div></div>\n<div>Terima kasih.</div>\n<div></div>\n<div><a href=\"{base_url}wp-content/uploads/2024/03/01778-20220210-Pengumuman-SWAB-Mahasiswa-12022022.pdf\" target=\"_blank\" rel=\"noopener\"><strong>Download</strong></a></div>\n<div></div>\n<div><a href=\"{base_url}wp-content/uploads/2024/03/01778-20220210-Pengumuman-SWAB-Mahasiswa-12022022.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">01778-20220210---Pengumuman-SWAB-Mahasiswa-12022022</a></div>\n', '<p>Kepada Yth. Mahasiswa/i Politeknik STMI Jakarta Berikut kami lampirkan informasikan Pelaksanaan SWAB Antigen Rutin Periode 1 Bagi Mahasiswa Politeknik STMI Jakarta Tahun Akademik 2021 Terima kasih. Download</p>\n', '1', '1637', 'publish', '2022-02-11 16:00:07', '2024-03-12 14:41:41', NULL, NULL);
