INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1656', 'pengumuman-pendaftaran-wisuda-2021', 'Pengumuman Pendaftaran Wisuda 2021', '<p>Diberitahukan kepada mahasiswa yang lulus di tahun 2021, dipersilhkan segera mendaftar wisuda. Persyaratan dan link pendaftaran dapat diunduh pada lampiran di bawah ini.</p>\n<p>&nbsp;</p>\n<p>Terima kasih</p>\n<p><strong><a href=\"{base_url}wp-content/uploads/2024/03/9d861-Pengumuman-Pendaftaran-Wisuda-4.pdf\" target=\"_blank\" rel=\"noopener\">Download</a></strong></p>\n<a href=\"{base_url}wp-content/uploads/2024/03/9d861-Pengumuman-Pendaftaran-Wisuda-4.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">9d861-Pengumuman-Pendaftaran-Wisuda---4</a>\n', '<p>Diberitahukan kepada mahasiswa yang lulus di tahun 2021, dipersilhkan segera mendaftar wisuda. Persyaratan dan link pendaftaran dapat diunduh pada lampiran di bawah ini. &nbsp; Terima kasih Download</p>\n', '1', '779', 'publish', '2021-10-15 15:00:38', '2024-03-12 15:01:41', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1659', 'prestasi-mahasiswa-politeknik-stmi-jakarta', 'Prestasi Mahasiswa Politeknik STMI Jakarta', '<p>Alhamdulillah Mahasiswa Prodi ABO angkatan 2017 (yang akan wisuda tahun ini) bernama Taufan Abdillah Jabar mengharumkan nama Politeknik STMI Jakarta dan DKI Jakarta karena telah mendapatkan medali Emas di Pon XX Tahun 2021, berita selengkapnya di <strong><a class=\"\" href=\"https://jakarta.suara.com/read/2021/10/14/210851/menang-tipis-atas-jabar-tim-bola-tangan-putra-dki-jakarta-raih-emas-pon-papua?page=all\" target=\"_blank\" rel=\"noopener\">suarajakarta.com</a></strong></p>\n', '<p>Alhamdulillah Mahasiswa Prodi ABO angkatan 2017 (yang akan wisuda tahun ini) bernama Taufan Abdillah Jabar mengharumkan nama Politeknik STMI Jakarta dan DKI Jakarta karena telah mendapatkan medali Emas di Pon XX Tahun 2021, berita selengkapnya di suarajakarta.com</p>\n', '1', '1660', 'publish', '2021-10-15 14:05:35', '2024-03-12 15:07:02', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1663', 'pengumuman-unggah-laporan-tugas-akhir-2021', 'Pengumuman Unggah Laporan Tugas Akhir 2021', '<p>Kepada mahasiswa Politeknik STMI Jakarta lulusan tahun 2021</p>\n<p>Sehubungan dengan implementasi repositori laporan Tugas Akhir, mahasiswa diwajibkan mengisi formulir Kelengkapan Data Laporan Tugas Akhir untuk Repositori melalui tautan: <a href=\"https://bit.ly/UnggahRepositoriSTMI\">https://bit.ly/UnggahRepositoriSTMI</a></p>\n<p><strong><a href=\"{base_url}wp-content/uploads/2024/03/2d445-Pengumuman-Unggah-Repositori-rev.pdf\" target=\"_blank\" rel=\"noopener\">Download</a></strong></p>\n<a href=\"{base_url}wp-content/uploads/2024/03/2d445-Pengumuman-Unggah-Repositori-rev.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">2d445-Pengumuman-Unggah-Repositori--rev</a>\n', '<p>Kepada mahasiswa Politeknik STMI Jakarta lulusan tahun 2021 Sehubungan dengan implementasi repositori laporan Tugas Akhir, mahasiswa diwajibkan mengisi formulir Kelengkapan Data Laporan Tugas Akhir untuk Repositori melalui tautan:  Download</p>\n', '1', '779', 'publish', '2021-10-13 15:08:22', '2024-03-12 15:09:41', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1666', 'pedoman-prakerin-yang-sudah-di-setujui-senat-dan-dibuat-sk-direktur-tanggal-5-juli-2021', 'Pedoman Prakerin Yang Sudah Di Setujui Senat Dan Dibuat SK Direktur Tanggal 5 Juli 2021', '<p>Pedoman Prakerin ini diperuntukan untuk mahasiswa yang mulai menyusun laporan prakerin mulai Agustus 2021. Adapun perincian sebagai berikut:</p>\n<ol>\n<li>Untuk Mahasiswa angkatan 2018 selain Prodi TKP yang menerapkan Prakerin 6 bulan dipersilahkan untuk hanya membuat Laporan Prakerin I saja.</li>\n<li>Untuk Mahasiswa Prodi TKP Tahun 2018 &amp; mahasiswa semua Prodi Tahun mulai angkatan 2019 (Kurikulum Dual Sistem) <strong>wajib </strong>membuat Laporan Prakerin I dan Laporan Prakerin II.</li>\n<li>Untuk semua mahasiswa yg berada di luar kondisi Poin 1 &amp; Poin 2. namun dalam tahap penyusunan Laporan Prakerin</li>\n</ol>\n<p>Terima kasih atas bantuan dan kerjasamanya.</p>\n<p><strong><a href=\"{base_url}wp-content/uploads/2024/03/325bd-Pedoman-Prakerin-SK-ttd-5-Juli-2021.pdf\" target=\"_blank\" rel=\"noopener\">Download</a></strong></p>\n<a href=\"{base_url}wp-content/uploads/2024/03/325bd-Pedoman-Prakerin-SK-ttd-5-Juli-2021.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">325bd-Pedoman-Prakerin--SK-ttd-5-Juli-2021</a>\n', '<p>Pedoman Prakerin ini diperuntukan untuk mahasiswa yang mulai menyusun laporan prakerin mulai Agustus 2021. Adapun perincian sebagai berikut: Untuk Mahasiswa angkatan 2018 selain Prodi TKP yang menerapkan Prakerin 6 bulan dipersilahkan untuk hanya membuat Laporan Prakerin I saja. Untuk Mahasiswa…</p>\n', '1', '779', 'publish', '2021-09-01 15:17:45', '2024-03-12 15:19:00', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1671', 'ujian-akhir-semester-pendek-semester-antara-periode-genap-online-tahun-akademik-2020-2021', 'Ujian Akhir Semester Pendek/ Semester Antara Periode Genap Online Tahun Akademik 2020/2021', '<p>Berikut Jadwal Ujian Akhir Semester Pendek/ Semester Antara Periode Genap Online Tahun Akademik 2020/2021</p>\n<p>Dokumen Terlampir</p>\n<p><a href=\"{base_url}wp-content/uploads/2024/03/f2022-Nomor-Surat-1892-Jadwal.pdf\" target=\"_blank\" rel=\"noopener\">Download</a></p>\n<a href=\"{base_url}wp-content/uploads/2024/03/f2022-Nomor-Surat-1892-Jadwal.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">f2022-Nomor-Surat-1892-Jadwal</a>\n', '<p>Berikut Jadwal Ujian Akhir Semester Pendek/ Semester Antara Periode Genap Online Tahun Akademik 2020/2021 Dokumen Terlampir Download</p>\n', '1', '779', 'publish', '2021-08-22 15:19:24', '2024-03-12 15:20:22', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1674', 'rekrutmen-tenant-inkubator-bisnis', 'Rekrutmen Tenant Inkubator Bisnis', '<p>Politeknik STMI Jakarta melalui Inkubator Bisnis mengundang para alumni dan mahasiswa untuk bisa bergabung di dalam program penumbuhan wirausaha baru. Adapun untuk jenis usaha yang akan dikembangkan adalah di bidang industri otomotif dan pendukungnya yang berfokus pada asesoris sepeda motor atau mobil, spare parts sepeda motor atau mobil, perbengkelan sepeda motor dan mobil, mold maker, pemesinan, komponen otomotif, dan industri jasa otomotif lainnya.</p>\n<p>Persyaratan yang harus dipenuhi oleh calon tenant dalam mengajukan diri (perorangan atau tim maksimal 3 orang) untuk menjadi tenant adalah sebagai berikut:</p>\n<ol>\n<li>Alumni Politeknik STMI Jakarta maksimum lulusan 7 (tujuh) tahun terakhir dan/atau  mahasiswa Politeknik STMI Jakarta minimal semester VI (enam) yang memiliki ide bisnis sesuai bidang fokus Inkubator Bisnis Politeknik STMI Jakarta.</li>\n<li>Menyampaikan dokumen proposal bisnis.</li>\n<li>Menyampaikan surat pernyataan mengikuti peraturan yang berlaku dalam menjalani proses inkubasi di Politeknik STMI Jakarta.</li>\n</ol>\n<p>Pelaksanaan seleksi calon tenant memiliki prosedur sebagai berikut :</p>\n<ol>\n<li>Calon tenant mendaftar dengan menyampaikan surat lamaran dan lampirannya melalui link berikut ini <a href=\"https://bit.ly/Pendaftaran-TenanT\" target=\"_blank\" rel=\"noopener\">https://bit.ly/Pendaftaran-TenanT</a></li>\n<li>Format proposal bisnis dan surat pernyataan dapat diunduh di pada link di atas.</li>\n<li>Seleksi berkas calon tenant.</li>\n<li>Seminar proposal bisnis dan wawancara calon tenant.</li>\n<li>Pengumuman hasil seleksi calon tenant.</li>\n</ol>\n<p><a href=\"{base_url}wp-content/uploads/2024/03/16b7f-Nomor-Surat-1629.pdf\" target=\"_blank\" rel=\"noopener\"><strong>Download</strong></a></p>\n<a href=\"{base_url}wp-content/uploads/2024/03/16b7f-Nomor-Surat-1629.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">16b7f-Nomor-Surat-1629</a>\n', '<p>Politeknik STMI Jakarta melalui Inkubator Bisnis mengundang para alumni dan mahasiswa untuk bisa bergabung di dalam program penumbuhan wirausaha baru. Adapun untuk jenis usaha yang akan dikembangkan adalah di bidang industri otomotif dan pendukungnya yang berfokus pada asesoris sepeda motor…</p>\n', '1', '779', 'publish', '2021-07-30 16:03:52', '2024-03-12 16:07:34', NULL, NULL);
