INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1721', 'kerja-prima-tanpa-benturan-kepentingan', 'Kerja Prima Tanpa Benturan Kepentingan', '<p><img fetchpriority=\"high\" fetchpriority=\"high\" decoding=\"async\" class=\"aligncenter wp-image-1722 size-large\" src=\"{base_url}wp-content/uploads/2024/03/Kerja-Prima-Tanpa-Benturan-Kepentingan-724x1024.jpeg\" alt=\"\" width=\"724\" height=\"1024\" srcset=\"{base_url}wp-content/uploads/2024/03/Kerja-Prima-Tanpa-Benturan-Kepentingan-724x1024.jpeg 724w, {base_url}wp-content/uploads/2024/03/Kerja-Prima-Tanpa-Benturan-Kepentingan-212x300.jpeg 212w, {base_url}wp-content/uploads/2024/03/Kerja-Prima-Tanpa-Benturan-Kepentingan-768x1086.jpeg 768w, {base_url}wp-content/uploads/2024/03/Kerja-Prima-Tanpa-Benturan-Kepentingan.jpeg 827w\" sizes=\"(max-width: 724px) 100vw, 724px\" /></p>\n<p>Setiap ASN termasuk pegawai Politeknik STMI Jakarta terkadang dalam pelaksanaan tugas mengalami kondisi berada diantara tugas dan kepentingan pribadi.</p>\n<p>Politeknik STMI Jakarta telah menetapkan prosedur untuk setiap pegawai dalam menangani adanya benturan kepentingan. Hal ini dilakukan dalam rangka memberikan pemahaman yang sama terkait penanganan Benturan Kepentingan.</p>\n<p>Melalui pemahaman terhadap Penanganan Benturan Kepentingan diharapkan mampu meningkatkan tata kelola pemerintahan yang baik (good government), menjaga integritas, mencegah korupsi serta menimbulkan perilaku positif dan kondusif</p>\n', '<p>Setiap ASN termasuk pegawai Politeknik STMI Jakarta terkadang dalam pelaksanaan tugas mengalami kondisi berada diantara tugas dan kepentingan pribadi. Politeknik STMI Jakarta telah menetapkan prosedur untuk setiap pegawai dalam menangani adanya benturan kepentingan. Hal ini dilakukan dalam rangka memberikan pemahaman…</p>\n', '1', '1722', 'publish', '2021-01-05 16:47:24', '2024-03-12 16:49:27', NULL, NULL);
