INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1886', 'pelaksanaan-pmb-online-gelombang-1-politeknik-stmi-jakarta-tahun-2020', 'PELAKSANAAN PMB ONLINE GELOMBANG 1 POLITEKNIK STMI JAKARTA TAHUN 2020', '<p>Pelaksanaan Penerimaan Mahasiswa Baru Gelombang 1 akan dilaksanakan pada tanggal 04 April 2020 secara online.</p>\n<p>Pelaksanaan ujian <strong>Jalur</strong> <strong>Regular</strong> (Tes TPA, TBI, dan Form Deskripsi Diri) dilaksanakan mulai pukul 09.00 WIB melalui <em>website</em> pmb.stmi.ac.id. Terkait dengan teknis jumlah soal, tipe soal, waktu pengerjaan, tata cara ujian dll dapat dibaca pada panduan teknis yang terlampir.</p>\n<p>Pelaksanaan ujian <strong>Jalur</strong> <strong>Prestasi</strong> (Wawancara) dilaksanakan melalui aplikasi Zoom mulai pukul 13.00 WIB (on time, keterlambatan dapat mengurani nilai), dimana <em>ID Meeting</em> untuk tiap-tiap peserta akan dikirimkan melalui SMS, Whatsapp dan email (harap simpan baik-baik dan jangan berikan ke siapapu termasuk yang mengaku panitia).Terkait dengan teknis wawancara mengenai dresscode, alokasi waktu, dan tata cara <em>login </em>dll dapat dibaca pada panduan teknis yang terlampir.</p>\n<p>Unduh ulang kartu ujian dimaksudkan untuk memastikan bahwa peserta sudah benar-benar terdaftar dan pembaruan data (jika ada), jika memang tidak terdapat perubahan tetap simpan kartu ujian terakhir yang diunduh untuk keperluan verifikasi lebih lanjut terkait daftar ulang.</p>\n<p>&nbsp;</p>\n<table style=\"height: 224px;\" border=\"0\" width=\"2381\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td></td>\n<td></td>\n<td>\n<p align=\"center\">Jakarta, 02 April 2020</p>\n<p align=\"center\">Direktur,</p>\n<p align=\"center\">ttd</p>\n<p align=\"center\">Mustofa</p>\n</td>\n</tr>\n</tbody>\n</table>\n<p><strong><a href=\"{base_url}wp-content/uploads/2020/04/854b8-ilovepdf_merged_compressed.pdf\" target=\"_blank\" rel=\"noopener\">Download</a></strong></p>\n<a href=\"{base_url}wp-content/uploads/2020/04/854b8-ilovepdf_merged_compressed.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">854b8-ilovepdf_merged_compressed</a>\n', '<p>Pelaksanaan Penerimaan Mahasiswa Baru Gelombang 1 akan dilaksanakan pada tanggal 04 April 2020 secara online. Pelaksanaan ujian Jalur Regular (Tes TPA, TBI, dan Form Deskripsi Diri) dilaksanakan mulai pukul 09.00 WIB melalui website pmb.stmi.ac.id. Terkait dengan teknis jumlah soal, tipe soal, waktu pengerjaan, tata cara…</p>\n', '1', '779', 'publish', '2020-04-02 09:13:17', '2024-03-13 09:15:46', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1891', 'informasi-pelaksanaan-pmb-gel-1', 'Informasi Pelaksanaan PMB Gel. 1', '<p>Bagi para peserta PMB yang sudah di validasi datanya di web pmb.stmi.ac.id harap dengan teliti membaca pengumuman di bawah ini:</p>\n<p>Sehubungan dengan Surat Edaran Menteri Perindustrian Nomor 3 Tahun 2020 tentang Perpanjangan Penghentian Sementara Kegiatan Perkantoran Dalam Rangka Mencegah Penyebaran Wabah CORONAVIRUS DISEASE (COVID-19) di Lingkungan Kementerian Perindustrian dan Surat Keputusan Kepala Badan Nasional Penaggulangan Bencana Nomor 13.A Tahun 2020 tentang Perpanjangan Status Keadaan Tertentu Darurat Bencana Wabah Penyakit Akibat Virus Corona Di Indonesia, maka panitia PMB Politeknik STMI Jakarta akan tetap menyelenggarakan ujian PMB Gelombang 1 dengan perubahan mekanisme yang sebelumnya offline (harus datang ke lokasi ujian) menjadi online melalui website <a href=\"http://pmb.stmi.ac.id/pengumuman_detail/pmb.stmi.ac.id\"><em>stmi.ac.id</em></a>.</p>\n<p>Peserta yang dapat mengikuti ujian PMB Gelombang 1 adalah peserta yang melakukan pembayaran biaya pendaftaran dari tanggal 1 Februari &#8211; 1 April 2020 dan telah melalui tahap validasi oleh panitia maksimal pada tanggal 2 April 2020.</p>\n<p>Peserta yang mendaftar PMB Gelombang 1 <strong>Jalur</strong> <strong>Regular</strong> akan mengikuti Ujian Online pada tanggal 4 April 2020 dimulai jam 09.00 WIB dengan materi TPA, TBI dan mengisi form deskripsi diri sebagai pengganti wawancara (petunjuk teknis terlampir).</p>\n<p>Peserta yang mendaftar PMB Gelombang 1 <strong>Jalur</strong> <strong>Prestasi</strong> akan mengikuti Wawancara Online via aplikasi ZOOM pada tanggal 4 April 2020 dimulai Jam 13.00 (lihat pengumuman selanjutnya untuk pembagian jam wawancara dan untuk petunjuk teknis terlampir).</p>\n<p>Seluruh peserta diharapkan untuk mengunduh ulang kartu peserta terkait dengan perubahan mekanisme diatas.</p>\n<p>&nbsp;</p>\n<p>Direktur,</p>\n<p>ttd</p>\n<p>Mustofa</p>\n<p>&nbsp;</p>\n<p><a href=\"{base_url}wp-content/uploads/2024/03/34c2c-Informasi-Pelaksanaan-PMB-Gel.-1-dan-Panduan-Ujian-PMB.pdf\" target=\"_blank\" rel=\"noopener\">Download</a></p>\n<a href=\"{base_url}wp-content/uploads/2024/03/34c2c-Informasi-Pelaksanaan-PMB-Gel.-1-dan-Panduan-Ujian-PMB.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">34c2c-Informasi-Pelaksanaan-PMB-Gel.-1-dan-Panduan-Ujian-PMB</a>\n', '<p>Bagi para peserta PMB yang sudah di validasi datanya di web pmb.stmi.ac.id harap dengan teliti membaca pengumuman di bawah ini: Sehubungan dengan Surat Edaran Menteri Perindustrian Nomor 3 Tahun 2020 tentang Perpanjangan Penghentian Sementara Kegiatan Perkantoran Dalam Rangka Mencegah Penyebaran…</p>\n', '1', '779', 'publish', '2020-03-31 09:17:19', '2024-03-13 09:18:31', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1894', 'informasi-perpanjangan-perkuliahan-jarak-jauh', 'Informasi Perpanjangan Perkuliahan Jarak Jauh', '<p>Berdasarkan Surat Edaran Menteri Perindustrian No 2 Tahun 2020 dan Kepgub DKI Jakarta No 337 Tahun 2020,</p>\n<p>Politeknik STMI Jakarta memutuskan untuk memperpanjang perkuliahan yang dilakukan dengan jarak jauh melalui situs <a href=\"http://www.pjj.stmi.ac.id/\" target=\"_blank\" rel=\"noopener\">www.pjj.stmi.ac.id</a> sampai tanggal 4 April 2020. Mohon sekiranya Tenaga Pengajar dan mahasiswa untuk menjalankan dengan baik.</p>\n<p>Untuk PNS, PPNPN dan mahasiswa Politeknik STMI Jakarta untuk melaksanakan tugas kedinasaannya di rumah/tempat tinggalnya (Work From Home/Study From Home) guna menjamin terlaksananya Tugas dan Fungsi Kementerian dengan Baik. Dan WAJIB tidak keluar dari rumah kecuali keadaan yang mendesak, menjaga pola hidup bersih dan sehat (PHBS).</p>\n<p>Ttd</p>\n<p>Direktur</p>\n', '<p>Berdasarkan Surat Edaran Menteri Perindustrian No 2 Tahun 2020 dan Kepgub DKI Jakarta No 337 Tahun 2020, Politeknik STMI Jakarta memutuskan untuk memperpanjang perkuliahan yang dilakukan dengan jarak jauh melalui situs www.pjj.stmi.ac.id sampai tanggal 4 April 2020. Mohon sekiranya Tenaga…</p>\n', '1', '779', 'publish', '2020-03-21 09:19:05', '2024-03-13 09:20:30', NULL, NULL);
