INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1907', 'jadwal-online-uts-genap-susulan-t-a-2019-2020', 'Jadwal ONLINE UTS Genap Susulan T.A. 2019/2020', '<p>Kepada Yth. Mahasiswa/i Politeknik STMI Jakarta</p>\n<p>Berikut kami informasikan Jadwal ONLINE Ujian Tengah Semester Genap Susulan Tahun Akademik 2019/2020 dengan file kami lampirkan pada tautan di bawah ini.</p>\n<p>Terima kasih.</p>\n<p><a href=\"{base_url}wp-content/uploads/2024/03/450d0-Jadwal-UTS-Genap-19-20-Pengganti-Online.pdf\" target=\"_blank\" rel=\"noopener\"><strong>Download</strong></a></p>\n<a href=\"{base_url}wp-content/uploads/2024/03/450d0-Jadwal-UTS-Genap-19-20-Pengganti-Online.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">450d0-Jadwal-UTS-Genap-19-20-Pengganti-Online</a>\n', '<p>Kepada Yth. Mahasiswa/i Politeknik STMI Jakarta Berikut kami informasikan Jadwal ONLINE Ujian Tengah Semester Genap Susulan Tahun Akademik 2019/2020 dengan file kami lampirkan pada tautan di bawah ini. Terima kasih. Download</p>\n', '1', '779', 'publish', '2020-05-25 09:06:26', '2024-03-15 09:07:32', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1910', 'pengumuman-covid-19', 'Pengumuman COVID-19', '<p>Edaran Direktur Politeknik STMI Jakarta</p>\n<p>&nbsp;</p>\n<p>Perkembangan COVID-19 cukup signifikan, membuat kami berkoordinasi dalam 2 hari terakhir sehingga mencapai suatu kesapakatan. Untuk mengurangi risiko penularan dan melakukan tindakan pencegahan, maka Politeknik STMI Jakarta memutuskan:</p>\n<p>&nbsp;</p>\n<p>1. *Meniadakan kegiatan mahasiswa di kampus selama 2 minggu ke depan mulai tanggal 16-27 Maret 2020.*</p>\n<p>&nbsp;</p>\n<p>2. *Menunda UTS Tanggal 16-20 Maret 2020*</p>\n<p>&nbsp;</p>\n<p>Jadwal UTS pengganti akan di selenggarakan pada *2-5 Juni 2020*</p>\n<p>&nbsp;</p>\n<p>UAS nya tetap tgl 8-19 Juni 2020</p>\n<p>&nbsp;</p>\n<p>3. *Perkuliahan Tetap di mulai Tanggal 23 Maret 2020* dengan Pembelajaran Jarak Jauh (PJJ)</p>\n<p>&nbsp;</p>\n<p>Akan di persiapkan sistem, mekanisme dan sosialisasi pada Dosen dan Mahasiswa perihal hal tersebut dalam waktu 1 minggu ini.</p>\n<p>&nbsp;</p>\n<p>4. Mohon mahasiswa dapat secara berkala memonitor ke website www.stmi.ac.id maupu media sosial Instagram @STMIJakarta untuk informasi lebih lanjut.</p>\n<p>&nbsp;</p>\n<p>5. Menyarankan kepada mahasiswa menerapkan</p>\n<p>&#8211; Pola Hidup Bersih Sehat (PHBS)</p>\n<p>&#8211; Melakukan belajar mandiri di rumah dan PJJ</p>\n<p>&#8211; Tinggal di rumah dan tidak berkumpul dalam keramaian maupun berpergian jauh.</p>\n<p>&nbsp;</p>\n<p>ttd</p>\n<p>Direktur Politeknik STMI Jakarta</p>\n', '<p>Edaran Direktur Politeknik STMI Jakarta &nbsp; Perkembangan COVID-19 cukup signifikan, membuat kami berkoordinasi dalam 2 hari terakhir sehingga mencapai suatu kesapakatan. Untuk mengurangi risiko penularan dan melakukan tindakan pencegahan, maka Politeknik STMI Jakarta memutuskan: &nbsp; 1. *Meniadakan kegiatan mahasiswa di…</p>\n', '1', '779', 'publish', '2020-03-15 09:19:06', '2024-03-15 09:21:52', NULL, NULL);
