INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1930', 'penjaringan-bakal-calon-direktur-politeknik-akom-dari-politeknik-stmi-jakarta', 'Penjaringan Bakal Calon Direktur Politeknik/Akom Dari Politeknik STMI Jakarta', '<p><img fetchpriority=\"high\" fetchpriority=\"high\" decoding=\"async\" class=\"aligncenter size-full wp-image-1931\" src=\"{base_url}wp-content/uploads/2024/03/cd289-penjaringan2.jpg\" alt=\"\" width=\"500\" height=\"250\" srcset=\"{base_url}wp-content/uploads/2024/03/cd289-penjaringan2.jpg 500w, {base_url}wp-content/uploads/2024/03/cd289-penjaringan2-300x150.jpg 300w\" sizes=\"(max-width: 500px) 100vw, 500px\" /></p>\n<p>Panitia Penjaringan Bakal Calon Direktur dari Politeknik STMI Jakarta, mengundang Bapak/Ibu Dosen pada Perguruan Tinggi Negeri untuk mendaftarkan diri sebagai Calon Direktur Politeknik/Akom di Lingkungan Kementerian Perindustrian periode 2020-2024.</p>\n<p>Jadwal Pelaksanaan Pemilihan Direktur sebagai berikut:</p>\n<ol>\n<li>Pendaftaran Bakal Calon Direktur: 26 Nov 2019 &#8211; 13 Des 2019</li>\n<li>Seleksi Administrasi: 23 Des 2019- 3 Jan 2020</li>\n<li>Surat Penyampaian Rekomendasi 3 Calon Direktur ke BPSDMI: 10 Jan 2020</li>\n</ol>\n<p>Berkas administrasi persyaratan dapat disampaikan kepada Sekretariat Penjaringan Bakal Calon Direktur dari Politeknik STMI Jakarta dengan alamat:</p>\n<p>Politeknik STMI Jakarta</p>\n<p>Ruang Senat Lt. 1<br />\nJl. Letjen Suprapto no.26 Cempaka Putih Jakarta, 10510<br />\nTelp. (021) 42886064, Fax (021) 42888206<br />\nEmail: seleksi.dir.stmi@stmi.ac.id atau seleksi.dir.stmi@gmail.com<br />\nCP: Yulius Jatmiko N(+628566061450) atau Ulil Hamida(+6285781036357)</p>\n<p>Persyaratan, Jadwal, dan Tamplate Dokumen Pendaftaran Direktur dapat diunduh di:</p>\n<p><a href=\"http://bit.ly/Pendaftaran-Direktur-2019\" target=\"_blank\" rel=\"noopener\">http://bit.ly/Pendaftaran-Direktur-2019</a></p>\n<p>atau</p>\n<p><a href=\"{base_url}wp-content/uploads/2024/03/Pendaftaran-Direktur-2019_-Template-Persyaratan.docx\" target=\"_blank\" rel=\"noopener\">Pendaftaran Direktur 2019_ Template Persyaratan</a></p>\n<p><a href=\"{base_url}wp-content/uploads/2024/03/Pendaftaran-Direktur-2019_-Persyaratan-dan-Jadwal.pdf\" target=\"_blank\" rel=\"noopener\">Pendaftaran Direktur 2019_ Persyaratan dan Jadwal</a></p>\n', '<p>Panitia Penjaringan Bakal Calon Direktur dari Politeknik STMI Jakarta, mengundang Bapak/Ibu Dosen pada Perguruan Tinggi Negeri untuk mendaftarkan diri sebagai Calon Direktur Politeknik/Akom di Lingkungan Kementerian Perindustrian periode 2020-2024. Jadwal Pelaksanaan Pemilihan Direktur sebagai berikut: Pendaftaran Bakal Calon Direktur: 26…</p>\n', '1', '1931', 'publish', '2019-11-29 10:34:15', '2024-03-15 10:05:25', NULL, NULL);
