INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1975', 'tutup-buku-pembayaran-akhir-tahun-2018', 'Tutup Buku Pembayaran Akhir Tahun 2018', '<p>Diberitahukan kepada seluruh mahasiswa Politeknik STMI Jakarta, bahwa disebabkan adanya Tutup Buku Akhir Tahun Anggaran 2018 maka mulai 29 Desember 2018 s/d 1 Januari 2019 Loket blanko pembayaran akan ditutup. Untuk itu diharapkan agar tidak melakukan transfer/transaksi pembayaran baik melalui Bank atau ATM Mandiri cabang manapun pada tanggal tersebut. Pembayaran akan dibuka kembali pada tanggal 2 Januari 2019.</p>\n<p>&nbsp;</p>\n<p>Terima Kasih</p>\n<p>File Pengumuman Terlampir</p>\n<p>&nbsp;</p>\n<p><img fetchpriority=\"high\" fetchpriority=\"high\" decoding=\"async\" class=\"aligncenter size-full wp-image-1976\" src=\"{base_url}wp-content/uploads/2024/03/0adf8-pengumuman-pembayaran.jpeg\" alt=\"\" width=\"780\" height=\"1040\" srcset=\"{base_url}wp-content/uploads/2024/03/0adf8-pengumuman-pembayaran.jpeg 780w, {base_url}wp-content/uploads/2024/03/0adf8-pengumuman-pembayaran-225x300.jpeg 225w, {base_url}wp-content/uploads/2024/03/0adf8-pengumuman-pembayaran-768x1024.jpeg 768w\" sizes=\"(max-width: 780px) 100vw, 780px\" /></p>\n<p>&nbsp;</p>\n', '<p>Diberitahukan kepada seluruh mahasiswa Politeknik STMI Jakarta, bahwa disebabkan adanya Tutup Buku Akhir Tahun Anggaran 2018 maka mulai 29 Desember 2018 s/d 1 Januari 2019 Loket blanko pembayaran akan ditutup. Untuk itu diharapkan agar tidak melakukan transfer/transaksi pembayaran baik melalui…</p>\n', '1', '779', 'publish', '2018-12-18 10:49:27', '2024-03-15 10:51:25', NULL, NULL);
