INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1995', 'surat-keterangan-perubahan-nama-sekolah-tinggi-ke-politeknik', 'Surat Keterangan Perubahan Nama Sekolah Tinggi Ke Politeknik', '<p>Berikut adalah Surat Keterangan perubahan nama institusi dari Sekolah Tinggi Manajemen Industri ke Politeknik STMI Jakarta.</p>\n<p>Surat tersebut dapat di download pada link di bawah ini:</p>\n<p><a href=\"{base_url}wp-content/uploads/2024/03/24eba-Surat-Keterangan-Alih-Bentuk-2018.pdf\" target=\"_blank\" rel=\"noopener\"><strong>Download</strong></a></p>\n<a href=\"{base_url}wp-content/uploads/2024/03/24eba-Surat-Keterangan-Alih-Bentuk-2018.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">24eba-Surat-Keterangan-Alih-Bentuk-2018</a>\n', '<p>Berikut adalah Surat Keterangan perubahan nama institusi dari Sekolah Tinggi Manajemen Industri ke Politeknik STMI Jakarta. Surat tersebut dapat di download pada link di bawah ini: Download</p>\n', '1', '779', 'publish', '2018-08-10 13:03:45', '2024-03-15 13:06:27', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('1998', 'pengumuman-jadwal-ujian-akhir-semester-genap-2017', 'Pengumuman Jadwal Ujian Akhir Semester Genap 2017', '<p>Sehubung dengan adanya PILKADA serentak di beberapa daerah yang akan berlangsung pada tanggal 27 Juni 2018 maka, Ujian Akhir Semester mengikuti jadwal yang telah ditetapkan, tetapi pada tanggal 27 Juni 2018 diundur menjadi tanggal 11 Juli 2018.</p>\n<p>&nbsp;</p>\n<p>Terima Kasih</p>\n<p>&nbsp;</p>\n<p>File Pengumuman Terlampir</p>\n<p><a href=\"{base_url}wp-content/uploads/2024/03/430c2-Pengunduruan-Jadwal-UAS-Periode-Genap-2017.pdf\" target=\"_blank\" rel=\"noopener\"><strong>Download</strong></a></p>\n<a href=\"{base_url}wp-content/uploads/2024/03/430c2-Pengunduruan-Jadwal-UAS-Periode-Genap-2017.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">430c2-Pengunduruan-Jadwal-UAS-Periode-Genap-2017</a>\n', '<p>Sehubung dengan adanya PILKADA serentak di beberapa daerah yang akan berlangsung pada tanggal 27 Juni 2018 maka, Ujian Akhir Semester mengikuti jadwal yang telah ditetapkan, tetapi pada tanggal 27 Juni 2018 diundur menjadi tanggal 11 Juli 2018. &nbsp; Terima Kasih…</p>\n', '1', '779', 'publish', '2018-06-08 13:09:39', '2024-03-15 13:17:21', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2001', 'resertifikasi-iso-9001', 'Resertifikasi ISO 9001', '<p>Politekni STMI Jakarta berhasil melakukan resertifikasi ISO 9001 pada tanggal 28 Maret 2018. Pada resertifikasi kali ini, Politeknik STMI Jakarta bahkan dapat melakukan Extension to Scope dari awalnya ISO 9001:2008 menjadi ISO 9001:2015. Resertifikasi tersebut diaudit oleh PT SAI Global.<br />\nDengan pencapaian sertifikasi ISO 9001:2015 tersebut tentunya menunjukkan peningkatan dan pemeliharaan sistem manajemen mutu di Politeknik STMI terus diupayakan agar visi misi Politeknik tercapai.</p>\n<a href=\"{base_url}wp-content/uploads/2018/05/7447b-Sert-ISO169-1.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">7447b-Sert-ISO169-1</a>\n', '<p>Politekni STMI Jakarta berhasil melakukan resertifikasi ISO 9001 pada tanggal 28 Maret 2018. Pada resertifikasi kali ini, Politeknik STMI Jakarta bahkan dapat melakukan Extension to Scope dari awalnya ISO 9001:2008 menjadi ISO 9001:2015. Resertifikasi tersebut diaudit oleh PT SAI Global.…</p>\n', '1', '2002', 'publish', '2018-05-07 14:00:09', '2024-03-15 13:22:29', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2008', 'komitmen-terhadap-zona-integritas', 'Komitmen Terhadap Zona Integritas', '<p><img fetchpriority=\"high\" fetchpriority=\"high\" decoding=\"async\" class=\"aligncenter wp-image-2009 size-full\" src=\"{base_url}wp-content/uploads/2024/03/Komitmen-Terhadap-Zona-Integritas.jpeg\" alt=\"\" width=\"1040\" height=\"780\" srcset=\"{base_url}wp-content/uploads/2024/03/Komitmen-Terhadap-Zona-Integritas.jpeg 1040w, {base_url}wp-content/uploads/2024/03/Komitmen-Terhadap-Zona-Integritas-300x225.jpeg 300w, {base_url}wp-content/uploads/2024/03/Komitmen-Terhadap-Zona-Integritas-1024x768.jpeg 1024w, {base_url}wp-content/uploads/2024/03/Komitmen-Terhadap-Zona-Integritas-768x576.jpeg 768w\" sizes=\"(max-width: 1040px) 100vw, 1040px\" /></p>\n<p>Komitmen terhadap pembangunan Zona Integritas terus ditingkatkan di Politeknik STMI Jakarta. Komitmen ini tentunya terus ditumbuhkan menjadi bagian tak terpisahkan dari seluruh sivitas akademika di Politeknik STMI Jakarta termasuk di dalamnya pimpinan, karyawan, dosen dan mahasiswa.<br />\nSalah satu bentuk komitmen adalah pelaksanaan sosialisasi mengenai aspek aspek zona integritas di lingkungan politeknik STMI Jakarta. Kali ini, sosialisasi yg dilaksanakan pada tanggal 19 April 2018 , mengangkat tema mengenai Bebas Korupsi. Dengan sosialisasi ini diharapkan seluruh sivitas akademika memahami bentuk bentuk korupsi dan berupaya menghindarinya.</p>\n', '<p>Komitmen terhadap pembangunan Zona Integritas terus ditingkatkan di Politeknik STMI Jakarta. Komitmen ini tentunya terus ditumbuhkan menjadi bagian tak terpisahkan dari seluruh sivitas akademika di Politeknik STMI Jakarta termasuk di dalamnya pimpinan, karyawan, dosen dan mahasiswa. Salah satu bentuk komitmen…</p>\n', '1', '2009', 'publish', '2018-04-20 13:20:05', '2024-03-15 13:20:54', NULL, NULL);
