INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2022', 'informasi-data-mahasiswa-i-pada-pddikti-pangkalan-data-pendidikan-tinggi', 'Informasi Data Mahasiswa/i Pada PDDikti (Pangkalan Data Pendidikan Tinggi)', '<p>Sehubungan dengan data Mahasiswa/i yang berada di Pangkalan Data Pendidikan Tinggi pada laman https://pddikti.kemdikbud.go.id/, maka perlu kami sampaikan bahwa data tersebut terupdate dari angkatan 2012, 2013, 2014 dst (lihat pada surat edaran hal 1 point 1.c).</p>\n<p>Adapun data sebelum angkatan 2012, Anda cukup datang ke Politeknik STMI Jakarta untuk verifikasi data (lihat pada surat edaran hal 2 point 2.c).</p>\n<p>&nbsp;</p>\n<p>Terima Kasih.</p>\n<p>Surat edaran tersebut bisa Anda download link di bawah ini:</p>\n<p><a href=\"{base_url}wp-content/uploads/2024/03/1ea05-Surat-Edaran-Periode-Awal-Pelaporan-PDDikti.pdf\" target=\"_blank\" rel=\"noopener\"><strong>Download</strong></a></p>\n<a href=\"{base_url}wp-content/uploads/2024/03/1ea05-Surat-Edaran-Periode-Awal-Pelaporan-PDDikti.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">1ea05-Surat-Edaran-Periode-Awal-Pelaporan-PDDikti</a>\n<p>&nbsp;</p>\n', '<p>Sehubungan dengan data Mahasiswa/i yang berada di Pangkalan Data Pendidikan Tinggi pada laman , maka perlu kami sampaikan bahwa data tersebut terupdate dari angkatan 2012, 2013, 2014 dst (lihat pada surat edaran hal 1 point 1.c). Adapun data sebelum angkatan 2012,…</p>\n', '1', '779', 'publish', '2017-12-28 13:33:38', '2024-03-15 13:34:51', NULL, NULL);
