INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2028', 'pengunduran-jadwal-reuni-akbar-stmi', 'Pengunduran Jadwal Reuni Akbar STMI', '<p>Kepada YTh, Bapak/Ibu Alumni STMI.</p>\n<p>Dalam rangka reuni akbar Alumni STMI dan Famgath, semula akan dilaksanakan pada 9-10 Desember 2017 karena banyaknya alumni yg memberikan konfirmasi tidak bisa hadir pada tgl tersebut dan belum memenuhi kuota pendaftaran minimum pemesanan paket meeting dan atas kebijakan Pengurus IKA maka Reuni di undur menjadi:</p>\n<p>Tanggal : 16-17 Desember 2017<br />\nTempat : Wisma Industri Puncak.</p>\n<p>biaya : 150 rb / orang tidak disediakan kamar dan menginap 250 rb/org dan perkeluarga 700rb</p>\n<p>Mohon di infokan kepada seluruh angkatan Alumni STMI, pendaftaran melalui: http://ika-stmi.com/?page=berita-7 or https://goo.gl/Udsc3Z</p>\n<p>1. Bapak Jouhari Dosen dan Alumni STMI tahun 80 (081585834353)<br />\n2. A. Juanda (081389686561)</p>\n<p>Mohon maaf atas di undurnya pelaksanaan reuni akbar ini dan mhn maklum dan kepada seluruh koordinator angkatan yg telah ditunjuk untuk menginformasikan d group WA angkatannya.<br />\nAtas perhatian dan kerjasama kami sampaikan terima kasih,</p>\n<p>Koord Angkatan Alumni STMI :</p>\n<p>1. Angkatan 70-79 Bapak Cundarmansyah,<br />\n2. Angkatan 80-82 Bapak Jouhari Maksudi 3. Angk 83 bapak syaiful,<br />\n4. angk 84 bapak Hendi,<br />\n5. Angk 85-86 bapak Zein Ginting,<br />\n6. Angk 87-89 bapak sulistianto,<br />\n7. Angk 90 bapak budi susatyo,<br />\n8. Angk 91 bapak andri hermawan,<br />\n9. angk 92 bapak budi,<br />\n10. angkatan 93 bapak Dicky,<br />\n11. Angk 94 bang zul,<br />\n12. Angk 95 bang Bayu,<br />\n13. Angkatan 96 bang Ikbal,<br />\n14. Angk 97 bang sopyan,<br />\n15. Angk 98 Bang Roby,<br />\n16. Angk 99 bang Fidiandri,<br />\n17. Angkatan 2000 Bro Syahroni,<br />\n18. Angk 2001 Sopyan Nawawi,<br />\n19. Angk 2002 Ricad,<br />\n20. Angk 2003 Budiman,<br />\n21. angkatan 2004-2005 Dodo<br />\n22. Angkatan 2006 Vicky<br />\n23. Angk 2007 &#8211; 2008 Faiz. dan angkatan 2009 &#8211; sekarang Andhika</p>\n<p>Terima Kasih atas perhatian dan Kerjasamanya. Hormat Kami :<br />\nZein Ginting (Ketum IKA) A. Juanda (Sekretaris IKA)</p>\n', '<p>Kepada YTh, Bapak/Ibu Alumni STMI. Dalam rangka reuni akbar Alumni STMI dan Famgath, semula akan dilaksanakan pada 9-10 Desember 2017 karena banyaknya alumni yg memberikan konfirmasi tidak bisa hadir pada tgl tersebut dan belum memenuhi kuota pendaftaran minimum pemesanan paket…</p>\n', '1', '779', 'publish', '2017-12-06 13:37:30', '2024-03-15 13:40:14', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2030', 'perubahan-denah-wisuda-2017', 'Perubahan Denah Wisuda 2017', '<p><strong>PENGUMUMAN LAYOUT TEMPAT DUDUK WISUDA</strong></p>\n<p>Layout Barisan dan Tempat Wisuda dan Gladi Resik Wisuda</p>\n<p>Gladi Resik : Senin, 4 Desember 2017, Pukul 13.00 WIB, di Aula Lt. 7 Politeknik STMI Jakarta</p>\n<p>Wisuda : Selasa, 5 Desember 2017, di Putri Duyung Convention Ancol</p>\n<p><strong><a href=\"{base_url}wp-content/uploads/2024/03/0bac1-Denah-Wisuda-2017.pdf.pdf\" target=\"_blank\" rel=\"noopener\">Download</a></strong></p>\n<a href=\"{base_url}wp-content/uploads/2024/03/0bac1-Denah-Wisuda-2017.pdf.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">0bac1-Denah-Wisuda-2017.pdf</a>\n', '<p>PENGUMUMAN LAYOUT TEMPAT DUDUK WISUDA Layout Barisan dan Tempat Wisuda dan Gladi Resik Wisuda Gladi Resik : Senin, 4 Desember 2017, Pukul 13.00 WIB, di Aula Lt. 7 Politeknik STMI Jakarta Wisuda : Selasa, 5 Desember 2017, di Putri Duyung…</p>\n', '1', '779', 'publish', '2017-12-04 13:42:13', '2024-03-15 13:44:10', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2033', 'reuni-akbar-alumni-stmi-dan-family-gathering', 'Reuni Akbar Alumni STMI Dan Family Gathering', '<p>Kepada YTh, Bapak/Ibu Alumni Sekolah Tinggi Manajemen Industri Kementerian Perindustrian.<br />\nDalam rangka reuni akbar Alumni STMI dan Famgath, semula akan dilaksanakan pada 2-3 Desember 2017 karena pada hari tsb libur panjang dan kamar tersedia tidak memenuhi dan d khawatirkan macet maka Reuni di undur menjadi:</p>\n<p>Tanggal : 9-10 Desember 2017<br />\nTempat : Wisma Industri Puncak. biaya : 350 rb/org (mbl pribadi), 400rb/org (naik bus) dan perkeluarga 700rb(mbl pribadi)</p>\n<p>Mohon di infokan kepada seluruh angkatan Alumni STMI, pendaftaran d mulai tgl 1 &#8211; 30 November 2017 di kampus melalui:<br />\n1. Bapak Jouhari Dosen dan Alumni STMI tahun 80 (081585834353)<br />\n2. Mba ela angkatan 94 sekretaris panitia.</p>\n<p>Atas perhatian dan kerjasama kami sampaikan terima kasih,<br />\nA. Juanda ( Sekretaris IKA)</p>\n<p>Koordinator Angkatan Alumni STMI :<br />\n1. Angkatan 70-79 Bapak Cundarmansyah,<br />\n2. Angkatan 80-82 Bapak Rasyid Hasan,<br />\n3. Angkatan 83 Bapak Syaiful,<br />\n4. Angkatan 84 Bapak Hendi,<br />\n5. Angkatan 85-86 Bapak Zein Ginting,<br />\n6. Angkatan 87-89 Bapak Sulistianto,<br />\n7. Angkatan 90 Bapak Budi Susatyo,<br />\n8. Angkatan 91 Bapak Andri Hermawan,<br />\n9. Angkatan 92 Bapak Budi,<br />\n10. Angkatan 93 Bapak Dicky,<br />\n11. Angkatan 94 Bang Zul,<br />\n12. Angkatan 95 Bang Bayu,<br />\n13. Angkatan 96 Bang Ikbal,<br />\n14. Angkatan 97 Bang Sopyan,<br />\n15. Angkatan 98 Bang Roby,<br />\n16. Angkatan 99 Bang Fidiandri,<br />\n17. Angkatan 2000 Bro Syahroni,<br />\n18. Angkatan 2001 Sopyan Nawawi,<br />\n19. Angkatan 2002 Ricad,<br />\n20. Angkatan 2003 Budiman,<br />\n21. Angkatan 2004-2006 Dodo<br />\n22. Angkatan 2007 &#8211; 2008 Faiz. dan Angkatan 2009 &#8211; sekarang Andhika<br />\nTerima Kasih atas perhatian dan Kerjasamanya.</p>\n', '<p>Kepada YTh, Bapak/Ibu Alumni Sekolah Tinggi Manajemen Industri Kementerian Perindustrian. Dalam rangka reuni akbar Alumni STMI dan Famgath, semula akan dilaksanakan pada 2-3 Desember 2017 karena pada hari tsb libur panjang dan kamar tersedia tidak memenuhi dan d khawatirkan macet…</p>\n', '1', '779', 'publish', '2017-10-31 13:50:23', '2024-03-15 13:52:24', NULL, NULL);
