INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2041', 'klarifikasi-koran-kompas-mengenai-stmi', 'Klarifikasi Koran Kompas Mengenai STMI', '<p><img fetchpriority=\"high\" fetchpriority=\"high\" decoding=\"async\" class=\"aligncenter size-full wp-image-2042\" src=\"{base_url}wp-content/uploads/2024/03/Klarifikasi-Koran-Kompas-Mengenai-STMI.jpeg\" alt=\"\" width=\"1152\" height=\"797\" srcset=\"{base_url}wp-content/uploads/2024/03/Klarifikasi-Koran-Kompas-Mengenai-STMI.jpeg 1152w, {base_url}wp-content/uploads/2024/03/Klarifikasi-Koran-Kompas-Mengenai-STMI-300x208.jpeg 300w, {base_url}wp-content/uploads/2024/03/Klarifikasi-Koran-Kompas-Mengenai-STMI-1024x708.jpeg 1024w, {base_url}wp-content/uploads/2024/03/Klarifikasi-Koran-Kompas-Mengenai-STMI-768x531.jpeg 768w\" sizes=\"(max-width: 1152px) 100vw, 1152px\" /></p>\n<p>Sehubung dengan diterbitkannya berita koran kompas pada tanggal 13 Oktober 2017 yang menuai kesalahan pemberitaan, maka pada tanggal 14 Oktober 2017 koran kompas meluruskan bahwa STMI dan STMII merupakan Perguruan Tinggi yang berbeda. <a href=\"{base_url}berita/tentang/berita_kampus/38/klarifikasi-mengenai-243-kampus-yang-dinonaktifkan.html\">Baca Juga Klarifikasi Mengenai 243 Kampus Yang Dinonaktifkan</a></p>\n<p>&nbsp;</p>\n', '<p>Sehubung dengan diterbitkannya berita koran kompas pada tanggal 13 Oktober 2017 yang menuai kesalahan pemberitaan, maka pada tanggal 14 Oktober 2017 koran kompas meluruskan bahwa STMI dan STMII merupakan Perguruan Tinggi yang berbeda. Baca Juga Klarifikasi Mengenai 243 Kampus Yang Dinonaktifkan…</p>\n', '1', '2042', 'publish', '2017-10-16 14:15:59', '2024-03-15 14:16:14', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2044', 'klarifikasi-mengenai-informasi-pada-koran-kompas', 'Klarifikasi Mengenai Informasi Pada Koran Kompas', '<p>Sehubungan dengan informasi yang tidak benar dari koran harian Kompas pada tanggal 13 Oktober 2017 mengenai &#8220;Pemerintah Cabut Izin 25 PTS&#8221; , dengan ini kami klarifikasi bahwa yang dimaksud adalah kampus STMII bukan STMI (Politeknik STMI Jakarta). Untuk informasi mengenai mengenai klarfikasi Kampus STMI tersebut dapat dilihat <a href=\"{base_url}berita/tentang/berita_kampus/38/klarifikasi-mengenai-243-kampus-yang-dinonaktifkan.html\">pada halaman Klarifikasi Mengenai 243 Kampus yang Dinonaktifkan.</a></p>\n<p>Kementerian Perindustrian juga akan meminta koran Kompas klarifikasi hal ini di penerbitan berikutnya.<br />\nTerima kasih, Pudir 1.</p>\n<p><img fetchpriority=\"high\" fetchpriority=\"high\" decoding=\"async\" class=\"aligncenter size-full wp-image-2048\" src=\"{base_url}wp-content/uploads/2024/03/Klarifikasi-Mengenai-Informasi-Pada-Koran-Kompas.jpg\" alt=\"\" width=\"540\" height=\"960\" srcset=\"{base_url}wp-content/uploads/2024/03/Klarifikasi-Mengenai-Informasi-Pada-Koran-Kompas.jpg 540w, {base_url}wp-content/uploads/2024/03/Klarifikasi-Mengenai-Informasi-Pada-Koran-Kompas-169x300.jpg 169w\" sizes=\"(max-width: 540px) 100vw, 540px\" /></p>\n', '<p>Sehubungan dengan informasi yang tidak benar dari koran harian Kompas pada tanggal 13 Oktober 2017 mengenai &#8220;Pemerintah Cabut Izin 25 PTS&#8221; , dengan ini kami klarifikasi bahwa yang dimaksud adalah kampus STMII bukan STMI (Politeknik STMI Jakarta). Untuk informasi mengenai…</p>\n', '1', '2048', 'publish', '2017-10-13 13:28:37', '2024-03-15 14:30:43', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2050', 'informasi-briefing-calon-mahasiswa-baru', 'Informasi Briefing Calon Mahasiswa Baru', '<p><img fetchpriority=\"high\" fetchpriority=\"high\" decoding=\"async\" class=\"aligncenter size-full wp-image-2051\" src=\"{base_url}wp-content/uploads/2024/03/402d3-Informasi-Mabar.png\" alt=\"\" width=\"980\" height=\"400\" srcset=\"{base_url}wp-content/uploads/2024/03/402d3-Informasi-Mabar.png 980w, {base_url}wp-content/uploads/2024/03/402d3-Informasi-Mabar-300x122.png 300w, {base_url}wp-content/uploads/2024/03/402d3-Informasi-Mabar-768x313.png 768w\" sizes=\"(max-width: 980px) 100vw, 980px\" /></p>\n<p>Bagi calon mahasiswa/i baru yang telah mendaftar ulang diwajibkan hadir pada Tanggal, 24 Agustus 2017, Jam 08.00 WIB bertempat di Kampus Politeknik STMI Jakarta, Jalan Letjen Suprapto No. 26 Cempaka Putih, Jakarta Pusat, dalam rangka pengarahan mahasiswa baru, dengan mengenakan pakaian : bagi Pria Kemeja Putih, Celana Hitam, Dasi Hitam Dan Bersepatu Hitam. Bagi Wanita Kemeja Putih, Celana/ Rok Hitam Dasi Hitam dan Bersepatu Hitam.</p>\n', '<p>Bagi calon mahasiswa/i baru yang telah mendaftar ulang diwajibkan hadir pada Tanggal, 24 Agustus 2017, Jam 08.00 WIB bertempat di Kampus Politeknik STMI Jakarta, Jalan Letjen Suprapto No. 26 Cempaka Putih, Jakarta Pusat, dalam rangka pengarahan mahasiswa baru, dengan mengenakan…</p>\n', '1', '2051', 'publish', '2017-08-14 14:47:56', '2024-03-15 14:48:59', NULL, NULL);
