INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2079', 'penyusunan-skema-kompetensi-lsp-politeknik-stmi-jakarta', 'Penyusunan Skema Kompetensi LSP Politeknik STMI Jakarta', '<p><img fetchpriority=\"high\" fetchpriority=\"high\" decoding=\"async\" class=\"aligncenter wp-image-2080 size-large\" src=\"{base_url}wp-content/uploads/2024/03/Penyusunan-Skema-Kompetensi-LSP-Politeknik-STMI-Jakarta-1024x682.jpg\" alt=\"\" width=\"1024\" height=\"682\" srcset=\"{base_url}wp-content/uploads/2024/03/Penyusunan-Skema-Kompetensi-LSP-Politeknik-STMI-Jakarta-1024x682.jpg 1024w, {base_url}wp-content/uploads/2024/03/Penyusunan-Skema-Kompetensi-LSP-Politeknik-STMI-Jakarta-300x200.jpg 300w, {base_url}wp-content/uploads/2024/03/Penyusunan-Skema-Kompetensi-LSP-Politeknik-STMI-Jakarta-768x512.jpg 768w, {base_url}wp-content/uploads/2024/03/Penyusunan-Skema-Kompetensi-LSP-Politeknik-STMI-Jakarta-1536x1024.jpg 1536w, {base_url}wp-content/uploads/2024/03/Penyusunan-Skema-Kompetensi-LSP-Politeknik-STMI-Jakarta.jpg 2000w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></p>\n<p>Kegiatan penyusunan skema Kompetensi LSP Politeknik STMI Jakarta dilakukan selama 3 hari yaitu tanggal 16-18 Februari 2017. Skema yang disusun nantinya akan diperuntukkan untuk mahasiswa Politeknik STMI Jakarta. Setiap program studi memiliki skema tersendiri yang disesuaikan dengan kompetensi yang dicapai oleh peserta didik.</p>\n', '<p>Kegiatan penyusunan skema Kompetensi LSP Politeknik STMI Jakarta dilakukan selama 3 hari yaitu tanggal 16-18 Februari 2017. Skema yang disusun nantinya akan diperuntukkan untuk mahasiswa Politeknik STMI Jakarta. Setiap program studi memiliki skema tersendiri yang disesuaikan dengan kompetensi yang dicapai…</p>\n', '1', '2080', 'publish', '2017-02-22 15:41:27', '2024-03-15 15:44:23', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2082', 'kartu-jakarta-mahasiswa-unggulan-kjmu', 'Kartu Jakarta Mahasiswa Unggulan (KJMU)', '<p>Terkait <span class=\"st\"><em>Kartu Jakarta Mahasiswa Unggulan</em> (KJMU) bahwa saat ini pihak Politeknik STMI Jakarta sedang menunggu kabar dari Pemprov DKI mengenai kemungkinan dibuatnya MoU antara Kementerian Perindustrian dengan Pemprov DKI Jakarta.</span></p>\n<p>Untuk itu yang dapat dilakukan oleh mahasiswa yang berdomisili di Jakarta adalah berkoordinasi dengan sekolah menengah asal untuk membuat baru / mengaktifkan kembali <em>Kartu Jakarta Pintar</em> (KJP) dan membuat surat permohonan agar diusulkan menjadi <em>Kartu Jakarta Mahasiswa Unggulan</em> (KJMU).</p>\n<p>Demikian Pemberitahuan ini kami sampaikan. Atas perhatiannya kami ucapkan terima kasih.</p>\n', '<p>Terkait Kartu Jakarta Mahasiswa Unggulan (KJMU) bahwa saat ini pihak Politeknik STMI Jakarta sedang menunggu kabar dari Pemprov DKI mengenai kemungkinan dibuatnya MoU antara Kementerian Perindustrian dengan Pemprov DKI Jakarta. Untuk itu yang dapat dilakukan oleh mahasiswa yang berdomisili di Jakarta adalah…</p>\n', '1', '779', 'publish', '2017-01-27 15:45:15', '2024-03-15 15:45:56', NULL, NULL);
