INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2201', 'serah-terima-jabatan-direktur-politeknik-stmi-jakarta', 'Serah Terima Jabatan Direktur Politeknik STMI Jakarta', '		<div data-elementor-type=\"wp-post\" data-elementor-id=\"2201\" class=\"elementor elementor-2201\">\n				<div class=\"elementor-element elementor-element-18ac24a9 e-flex e-con-boxed e-con e-parent\" data-id=\"18ac24a9\" data-element_type=\"container\" data-settings=\"{&quot;background_background&quot;:&quot;classic&quot;}\">\n					<div class=\"e-con-inner\">\n				<div class=\"elementor-element elementor-element-ef367ef elementor-arrows-position-inside elementor-pagination-position-outside elementor-widget elementor-widget-image-carousel\" data-id=\"ef367ef\" data-element_type=\"widget\" data-settings=\"{&quot;navigation&quot;:&quot;both&quot;,&quot;autoplay&quot;:&quot;yes&quot;,&quot;pause_on_hover&quot;:&quot;yes&quot;,&quot;pause_on_interaction&quot;:&quot;yes&quot;,&quot;autoplay_speed&quot;:5000,&quot;infinite&quot;:&quot;yes&quot;,&quot;speed&quot;:500}\" data-widget_type=\"image-carousel.default\">\n				<div class=\"elementor-widget-container\">\n							<div class=\"elementor-image-carousel-wrapper swiper\" role=\"region\" aria-roledescription=\"carousel\" aria-label=\"Image Carousel\" dir=\"ltr\">\n			<div class=\"elementor-image-carousel swiper-wrapper\" aria-live=\"off\">\n								<div class=\"swiper-slide\" role=\"group\" aria-roledescription=\"slide\" aria-label=\"1 of 3\"><figure class=\"swiper-slide-inner\"><img decoding=\"async\" class=\"swiper-slide-image\" src=\"{base_url}wp-content/uploads/2024/06/Snapinsta.app_441495627_18135703117335746_6577477131129577311_n_1080.jpg\" alt=\"Snapinsta.app_441495627_18135703117335746_6577477131129577311_n_1080\" /></figure></div><div class=\"swiper-slide\" role=\"group\" aria-roledescription=\"slide\" aria-label=\"2 of 3\"><figure class=\"swiper-slide-inner\"><img decoding=\"async\" class=\"swiper-slide-image\" src=\"{base_url}wp-content/uploads/2024/06/Snapinsta.app_441536053_18135703126335746_227252817560298425_n_1080.jpg\" alt=\"Snapinsta.app_441536053_18135703126335746_227252817560298425_n_1080\" /></figure></div><div class=\"swiper-slide\" role=\"group\" aria-roledescription=\"slide\" aria-label=\"3 of 3\"><figure class=\"swiper-slide-inner\"><img decoding=\"async\" class=\"swiper-slide-image\" src=\"{base_url}wp-content/uploads/2024/06/Snapinsta.app_441499701_18135703108335746_94130599648462074_n_1080.jpg\" alt=\"Snapinsta.app_441499701_18135703108335746_94130599648462074_n_1080\" /></figure></div>			</div>\n												<div class=\"elementor-swiper-button elementor-swiper-button-prev\" role=\"button\" tabindex=\"0\">\n						<svg aria-hidden=\"true\" class=\"e-font-icon-svg e-eicon-chevron-left\" viewBox=\"0 0 1000 1000\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M646 125C629 125 613 133 604 142L308 442C296 454 292 471 292 487 292 504 296 521 308 533L604 854C617 867 629 875 646 875 663 875 679 871 692 858 704 846 713 829 713 812 713 796 708 779 692 767L438 487 692 225C700 217 708 204 708 187 708 171 704 154 692 142 675 129 663 125 646 125Z\"></path></svg>					</div>\n					<div class=\"elementor-swiper-button elementor-swiper-button-next\" role=\"button\" tabindex=\"0\">\n						<svg aria-hidden=\"true\" class=\"e-font-icon-svg e-eicon-chevron-right\" viewBox=\"0 0 1000 1000\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M696 533C708 521 713 504 713 487 713 471 708 454 696 446L400 146C388 133 375 125 354 125 338 125 325 129 313 142 300 154 292 171 292 187 292 204 296 221 308 233L563 492 304 771C292 783 288 800 288 817 288 833 296 850 308 863 321 871 338 875 354 875 371 875 388 867 400 854L696 533Z\"></path></svg>					</div>\n				\n									<div class=\"swiper-pagination\"></div>\n									</div>\n						</div>\n				</div>\n				<div class=\"elementor-element elementor-element-280c8963 elementor-widget elementor-widget-text-editor\" data-id=\"280c8963\" data-element_type=\"widget\" data-widget_type=\"text-editor.default\">\n				<div class=\"elementor-widget-container\">\n									<p>Jakarta, 22 Mei 2024 – Telah dilaksanakan serah terima jabatan (sertijab) Direktur Politeknik STMI Jakarta dari Bapak Mustofa kepada Bapak Amrin Rapi di Badan Pengembangan Sumber Daya Manusia Industri (BPSDMI) Jakarta.</p><p><span style=\"font-family: inherit; font-size: inherit; font-style: inherit; font-variant-ligatures: inherit; font-variant-caps: inherit; font-weight: inherit; text-align: var(--text-align); color: var(--theme-text-color); letter-spacing: var(--theme-letter-spacing); text-transform: var(--theme-text-transform);\">Acara sertijab ini dipimpin langsung oleh Kepala BPSDMI Bapak Masrokhan dan disaksikan oleh jajaran pimpinan BPSDMI dan Para tamu undangan.</span></p><p>Kami percaya bahwa Bapak Amrin Rapi akan membawa visi, komitmen, dan kepemimpinan yang kuat untuk memajukan Politeknik STMI Jakarta ke tingkat yang lebih tinggi dalam bidang pendidikan dan pengembangan sumber daya manusia.</p><p>Selamat kepada Bapak Amrin Rapi atas terpilihnya sebagai Direktur Politeknik STMI Jakarta. Kami berharap dukungan penuh dari seluruh anggota civitas akademika untuk mewujudkan visi dan misi bersama demi kemajuan institusi kita.</p><p>—————————<br />Join us 📲<br />Website : www.stmi.ac.id<br />IG: @stmijakarta<br />Twitter: @stmijakarta<br />Facebook: Politeknik STMI Jakarta<br />WA : 085155244455<br />—————————<br />Kementerian Perindustrian RI<br />#politeknikstmijakarta<br />#Politeknik<br />#STMIJakarta<br />#STMImenujuWBK<br />#Kampus<br />#VokasiKompeten<br />#SobatIndustri<br />#JoinSTMI<br />#kementerianperindustrian</p>								</div>\n				</div>\n					</div>\n				</div>\n				</div>\n		', '<p>Jakarta, 22 Mei 2024 – Telah dilaksanakan serah terima jabatan (sertijab) Direktur Politeknik STMI Jakarta dari Bapak Mustofa kepada Bapak Amrin Rapi di Badan Pengembangan Sumber Daya Manusia Industri (BPSDMI) Jakarta. Acara sertijab ini dipimpin langsung oleh Kepala BPSDMI Bapak…</p>\n', '1', '2205', 'publish', '2024-05-22 17:42:59', '2026-09-18 19:53:13', 'post-2201', 'post-2201');
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2223', 'perpanjangan-perjanjian-kerja-sama-pelaksanaan-pelatihan-setara-diploma-1-antara-politeknik-stmi-jakarta-dengan-pt-komatsu-indonesia', 'Perpanjangan Perjanjian Kerja Sama Pelaksanaan Pelatihan Setara Diploma 1 antara Politeknik STMI Jakarta dengan PT Komatsu Indonesia', '		<div data-elementor-type=\"wp-post\" data-elementor-id=\"2223\" class=\"elementor elementor-2223\">\n				<div class=\"elementor-element elementor-element-5787c5e1 e-flex e-con-boxed e-con e-parent\" data-id=\"5787c5e1\" data-element_type=\"container\" data-settings=\"{&quot;background_background&quot;:&quot;gradient&quot;}\">\n					<div class=\"e-con-inner\">\n				<div class=\"elementor-element elementor-element-2300ac9 elementor-arrows-position-inside elementor-pagination-position-outside elementor-widget elementor-widget-image-carousel\" data-id=\"2300ac9\" data-element_type=\"widget\" data-settings=\"{&quot;navigation&quot;:&quot;both&quot;,&quot;autoplay&quot;:&quot;yes&quot;,&quot;pause_on_hover&quot;:&quot;yes&quot;,&quot;pause_on_interaction&quot;:&quot;yes&quot;,&quot;autoplay_speed&quot;:5000,&quot;infinite&quot;:&quot;yes&quot;,&quot;speed&quot;:500}\" data-widget_type=\"image-carousel.default\">\n				<div class=\"elementor-widget-container\">\n							<div class=\"elementor-image-carousel-wrapper swiper\" role=\"region\" aria-roledescription=\"carousel\" aria-label=\"Image Carousel\" dir=\"ltr\">\n			<div class=\"elementor-image-carousel swiper-wrapper\" aria-live=\"off\">\n								<div class=\"swiper-slide\" role=\"group\" aria-roledescription=\"slide\" aria-label=\"1 of 4\"><figure class=\"swiper-slide-inner\"><img decoding=\"async\" class=\"swiper-slide-image\" src=\"{base_url}wp-content/uploads/2024/06/447223631_18137127829335746_4513380392227521400_n-819x1024.jpg\" alt=\"447223631_18137127829335746_4513380392227521400_n\" /></figure></div><div class=\"swiper-slide\" role=\"group\" aria-roledescription=\"slide\" aria-label=\"2 of 4\"><figure class=\"swiper-slide-inner\"><img decoding=\"async\" class=\"swiper-slide-image\" src=\"{base_url}wp-content/uploads/2024/06/446873615_18137127820335746_3301564612969040832_n-819x1024.jpg\" alt=\"446873615_18137127820335746_3301564612969040832_n\" /></figure></div><div class=\"swiper-slide\" role=\"group\" aria-roledescription=\"slide\" aria-label=\"3 of 4\"><figure class=\"swiper-slide-inner\"><img decoding=\"async\" class=\"swiper-slide-image\" src=\"{base_url}wp-content/uploads/2024/06/447022801_18137127811335746_5447640532234453967_n-819x1024.jpg\" alt=\"447022801_18137127811335746_5447640532234453967_n\" /></figure></div><div class=\"swiper-slide\" role=\"group\" aria-roledescription=\"slide\" aria-label=\"4 of 4\"><figure class=\"swiper-slide-inner\"><img decoding=\"async\" class=\"swiper-slide-image\" src=\"{base_url}wp-content/uploads/2024/06/447277849_18137127793335746_8738402267008231500_n-819x1024.jpg\" alt=\"447277849_18137127793335746_8738402267008231500_n\" /></figure></div>			</div>\n												<div class=\"elementor-swiper-button elementor-swiper-button-prev\" role=\"button\" tabindex=\"0\">\n						<svg aria-hidden=\"true\" class=\"e-font-icon-svg e-eicon-chevron-left\" viewBox=\"0 0 1000 1000\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M646 125C629 125 613 133 604 142L308 442C296 454 292 471 292 487 292 504 296 521 308 533L604 854C617 867 629 875 646 875 663 875 679 871 692 858 704 846 713 829 713 812 713 796 708 779 692 767L438 487 692 225C700 217 708 204 708 187 708 171 704 154 692 142 675 129 663 125 646 125Z\"></path></svg>					</div>\n					<div class=\"elementor-swiper-button elementor-swiper-button-next\" role=\"button\" tabindex=\"0\">\n						<svg aria-hidden=\"true\" class=\"e-font-icon-svg e-eicon-chevron-right\" viewBox=\"0 0 1000 1000\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M696 533C708 521 713 504 713 487 713 471 708 454 696 446L400 146C388 133 375 125 354 125 338 125 325 129 313 142 300 154 292 171 292 187 292 204 296 221 308 233L563 492 304 771C292 783 288 800 288 817 288 833 296 850 308 863 321 871 338 875 354 875 371 875 388 867 400 854L696 533Z\"></path></svg>					</div>\n				\n									<div class=\"swiper-pagination\"></div>\n									</div>\n						</div>\n				</div>\n				<div class=\"elementor-element elementor-element-45546903 elementor-widget elementor-widget-text-editor\" data-id=\"45546903\" data-element_type=\"widget\" data-widget_type=\"text-editor.default\">\n				<div class=\"elementor-widget-container\">\n									<p>Jakarta, 5 Juni 2024 telah dilaksanakan kegiatan Perpanjangan Perjanjian Kerja Sama Pelaksanaan Pelatihan Setara Diploma 1 antara Politeknik STMI Jakarta dengan PT Komatsu Indonesia.</p><p><span style=\"font-family: inherit; font-size: inherit; font-style: inherit; font-variant-ligatures: inherit; font-variant-caps: inherit; font-weight: inherit; text-align: var(--text-align); color: var(--theme-text-color); letter-spacing: var(--theme-letter-spacing); text-transform: var(--theme-text-transform);\">Turut hadir juga Kepala BPSDMI Drs. Masrokhan, MAP, CGCAE untuk menyaksikan Perpanjangan Perjanjian Kerja Sama Pelaksanaan Pelatihan Setara Diploma 1 antara Politeknik STMI Jakarta dengan PT Komatsu Indonesia</span></p><p><span style=\"font-family: inherit; font-size: inherit; font-style: inherit; font-variant-ligatures: inherit; font-variant-caps: inherit; font-weight: inherit; text-align: var(--text-align); color: var(--theme-text-color); letter-spacing: var(--theme-letter-spacing); text-transform: var(--theme-text-transform);\">Kegiatan ini diharapkan dapat memperkuat hubungan kerjasama antara institusi pendidikan dan industri.</span></p><p>————————— <br />Join us 📲 <br />Website : www.stmi.ac.id<br />IG: @stmijakarta<br />Twitter: @stmijakarta<br />Facebook: Politeknik STMI Jakarta<br />WA : 085155244455</p><p>—————————<br />Kementerian Perindustrian RI<br />#politeknikstmijakarta <br />#Politeknik<br />#STMIJakarta<br />#STMIWBK<br />#STMIMenujuWBBM<br />#Kampus<br />#VokasiKompeten<br />#SobatIndustri<br />#JoinSTMI<br />#kementerianperindustrian<br />#kegiatankampus</p><div> </div>								</div>\n				</div>\n					</div>\n				</div>\n				</div>\n		', '<p>&nbsp; Jakarta, 5 Juni 2024 telah dilaksanakan kegiatan Perpanjangan Perjanjian Kerja Sama Pelaksanaan Pelatihan Setara Diploma 1 antara Politeknik STMI Jakarta dengan PT Komatsu Indonesia. Turut hadir juga Kepala BPSDMI Drs. Masrokhan, MAP, CGCAE untuk menyaksikan Perpanjangan Perjanjian Kerja Sama…</p>\n', '1', '2224', 'publish', '2024-06-05 23:31:52', '2024-06-05 23:31:52', 'post-2223', 'post-2223');
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2234', 'politeknik-stmi-jakarta-dan-pt-komatsu-indonesia-plant-cilincing-sepakati-perjanjian-kerja-sama-bidang-pendidikan', 'Politeknik STMI Jakarta dan PT Komatsu Indonesia Plant Cilincing Sepakati Perjanjian Kerja Sama Bidang Pendidikan', '<div class=\"page\" title=\"Page 1\">\n<div class=\"layoutArea\">\n<div class=\"column\">\n<p>Politeknik STMI Jakarta menjalin kerja sama dengan PT Komatsu Indonesia Plant Cilincing tentang Penyelenggaraan dan Pengembangan Program Pendidikan Setara Diploma I Vokasi Industri. Kegiatan ini dilaksanakan di Aula Gedung Employee Center PT Komatsu Indonesia Plant Cilincing, Jakarta, Rabu (5/6) kemarin.</p>\n<p>Adapun penandatanganan Perjanjian Kerja Sama dilakukan oleh Direktur Politeknik STMI Jakarta Amrin Rapi bersama Presiden Direktur PT Komatsu Indonesia Jamalludin dan disaksikan Kepala Badan Pengembangan Sumber Daya Manusia Industri Kementerian Perindustrian Masrokhan.</p>\n<p>“Bahwa strategi peningkatan SDM melalui Program Diploma, memberikan banyak manfaat dan hasil dari Program Diploma ini sudah terimplementasi di PT Komatsu Indonesia. Program Diploma juga mengajak perusahaan mitra Komatsu untuk berpartisipasi dalam setiap Batch. Saat ini kita sudah memasuki Batch 5 dimana jumlah dari peserta Program Diploma mengalami peningkatan dari Batch sebelumnya,” papar Rudi Kurnianto Direktur Administrasi Komatsu Indonesia.</p>\n<p>Pada kesempatan ini Jamalludin Selaku Presiden Direktur PT Komatsu Indonesia menyambut baik kedatangan Politeknik STMI Jakarta dan kerja sama yang telah disepakati. “Program Diploma memberikan dampak yang baik kepada perusahaan dan juga memberikan kesempatan kepada karyawan PT Komatsu untuk mengembangkan diri. Dengan SDM yang berkualitas dan berdaya saing maka akan dapat memenuhi ekspektasi dari peningkatan perkembangan industri alat berat di bidang Konstruksi, Agro, dan Pertambangan” Ujarnya dalam keterangannya (5/6).</p>\n<p>Kepala BPSDMI, menjelaskan Perkembangan industri alat berat memegang peranan penting dalam perekonomian Indonesia, sehingga SDM perusahaan akan menjadi aset yang penting untuk diperhatikan.</p>\n<p>“Program Pendidikan Setara Diploma 1 Manufaktur Alat Berat ini menjadi salah satu solusi untuk pembentukan SDM yang kompeten. BPSDMI berkomitmen mendukung penuh pengembangan SDM Industri yang berkualitas dan berdaya saing di sektor industri alat berat,” Lanjut Masrokhan.</p>\n</div>\n</div>\n</div>\n<div class=\"page\" title=\"Page 2\">\n<div class=\"layoutArea\">\n<div class=\"column\">\n<p>Mengutip keterangan yang diberikan Menteri Perindustrian Agus Gumiwang Kartasasmita pada Senin (29/4) di Jakarta, “Penyelenggaraan pendidikan dan pelatihan di unit pendidikan Kemenperin bertujuan untuk memenuhi kebutuhan tenaga kerja kompeten di sektor industri manufaktur. Karena itu, dibutuhkan kerja sama dengan industri agar unit pendidikan tersebut selaras dengan demand industri saat ini,”</p>\n<p>Pada penandatangan perjanjian kerja sama kemarin (5/6), ada tiga rangkaian kegiatan utama, meliputi Plant Tour. Kepala BPSDMI dan Direktur Politeknik STMI Jakarta beserta jajarannya melakukan Plant Tour untuk dapat menambah wawasan praktis mengenai PT Komatsu Indonesia, serta melihat hasil atau produk yang dihasilkan dari Program kelas Industri yang terimplementasi di PT Komatsu Indonesia.</p>\n<p>Kedua, meresmikan pembukaan program setara D1 Manufaktur Alat Berat Batch 5 di Politeknik STMI Jakarta, selanjutnya ketiga meresmikan kerja sama antara Politeknik STMI Jakarta dan PT Komatsu Indonesia yang disaksikan oleh Kepala Badan Pengembangan Sumber Daya Manusia Industri (BPSDMI) melalui penandatanganan Perjanjian Kerja Sama Program Diploma 1.</p>\n<p>Harapan dari kegiatan penandatanganan PKS ini, terdapat keberlanjutan dalam pembangunan SDM industri yang berkualitas dan berdaya saing utamanya di Industri alat berat.</p>\n</div>\n</div>\n</div>\n', '<p>Politeknik STMI Jakarta menjalin kerja sama dengan PT Komatsu Indonesia Plant Cilincing tentang Penyelenggaraan dan Pengembangan Program Pendidikan Setara Diploma I Vokasi Industri. Kegiatan ini dilaksanakan di Aula Gedung Employee Center PT Komatsu Indonesia Plant Cilincing, Jakarta, Rabu (5/6) kemarin.…</p>\n', '2', '2235', 'publish', '2024-06-10 11:39:58', '2024-06-10 11:39:58', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2250', 'pelatihan-service-excellence-tenaga-kependidikan-politeknik-stmi-jakarta', 'Pelatihan Service Excellence Tenaga Kependidikan Politeknik STMI Jakarta', '<p>Jakarta &#8211; Politeknik STMI Jakarta melaksanakan pelatihan Service Excellent yang diberi tema “Raih Predikat Wilayah Birokrasi Bersih dan Melayani (WBBM), Wujudkan Pelayanan Publik yang Berkualitas”,  di Bogor (24/6).</p>\n<p><em>Service Excellence</em> atau Pelayanan prima merupakan tindakan atau upaya yang dilakukan perusahaan atau organisasi tertentu untuk memberikan pelayanan maksimal dengan tujuan agar pelanggan atau masyarakat bisa mendapatkan kepuasan atas pelayanan yang dilakukan.</p>\n<p>Tujuan diadakan kegiatan pelatihan <em>service excellence </em>ini untuk mengenal teori tentang <em>Service Excellence</em> prinsip dasar komunikasi dan teknik <em>handling customer complaint</em>, mampu mempraktekan bagaimana memberikan pelayanan prima kepada masyarakat, meningkatkan kinerja dan pelayanan tenaga kependidikan baru sehingga memberikan layanan prima di setiap unit – unit di lingkungan Politeknik STMI Jakarta, serta penguatan kualitas pelayanan publik untuk membangun zona integritas menuju Wilayah Birokrasi Bersih dan Melayani (WBBM) dan mampu menyampaikan informasi atau pesan dengan jelas kepada <em>stakeholder</em>. Pelatihan Tersebut dilaksanakan selama 3 (tiga) hari dari tanggal 24 Juni sampai 26 Juni 2024.</p>\n<p>Direktur Politeknik STMI Jakarta Amrin Rapi membuka dan memberikan arahan pada peserta pelatihan, “Mimpi Kementerian Perindustrian punya Sekolah adalah menyiapkan Sumber Daya Manusia Industri, sehingga kita semua harus membantu dan mendukung Kementerian Perindustrian”. Ujar Amrin.</p>\n<p>Hari pertama pelatihan <em>service excellence </em>(24/6) diisi oleh Azizah Hanum, Azizah Hanum merupakan <em>News Anchor</em> Liputan 6 SCTV. Wanita yang kerap di sapa Hanum ini mengisi materi Public Speaking, diantaranya tentang cara melakukan public speaking, cara mengatasi takut berbicara di depan umum, dan praktek <em>public speaking.</em></p>\n<p>Setelahnya dilanjut dengan materi peningkatan kualitas pegawai yang diisi oleh Tim Kepegawaian Politeknik STMI Jakarta.</p>\n<p>Hari kedua Pelatihan (25/4) diawali dengan kegiatan <em>team building</em> yang diikuti oleh seluruh peserta pelatihan, dan dilanjut dengan materi Pelayanan Prima Modern dan Komunikasi Yang Efektif Dalam Melayani Pelanggan dan <em>Handling Costumer</em>  yang diberikan oleh Faried Kassa dari <em>Trainer</em> Selaras <em>Consulting</em>, dan dilanjut oleh Tina Martina (Direktur Politeknik STTT Bandung periode 2016-2024).</p>\n<p>Bahwa ada perbedaan ketika mempersiapkan WBK dan WBBM, perbedaan yang mencolok adalah Inovasi. Inovasi yang internal, yang harus dibangun dari dalam diri kita sendiri, ujar Tina.</p>\n<p>Hari Ketiga Pelatihan (26/4) Materi terakhir tentang Zona Integritas Menuju Wilayah Birokrasi Bersih dan Melayani (WBBM) yang disampaikan oleh Praharani Anjasmara Raganingrum, S.E., M.E,</p>\n<p>Dalam materinya Praharani menyampaikan bahwa ketika sudah WBK, maka seluruh kegiatan terus diperbaiki dan ditingkatan serta seluruh kegiatan akan dikroscek dan dievaluasi nantinya.</p>\n<p>Akhir dari kegiatan pelatihan service excellence dilakukan Posttest dan Evaluasi serta penutupan.</p>\n<p><img fetchpriority=\"high\" fetchpriority=\"high\" decoding=\"async\" class=\"alignnone wp-image-2246\" src=\"{base_url}wp-content/uploads/2024/07/Pelatihan-300x169.jpg\" alt=\"\" width=\"427\" height=\"241\" srcset=\"{base_url}wp-content/uploads/2024/07/Pelatihan-300x169.jpg 300w, {base_url}wp-content/uploads/2024/07/Pelatihan-1024x576.jpg 1024w, {base_url}wp-content/uploads/2024/07/Pelatihan-768x432.jpg 768w, {base_url}wp-content/uploads/2024/07/Pelatihan.jpg 1489w\" sizes=\"(max-width: 427px) 100vw, 427px\" /></p>\n', '<p>Jakarta &#8211; Politeknik STMI Jakarta melaksanakan pelatihan Service Excellent yang diberi tema “Raih Predikat Wilayah Birokrasi Bersih dan Melayani (WBBM), Wujudkan Pelayanan Publik yang Berkualitas”,  di Bogor (24/6). Service Excellence atau Pelayanan prima merupakan tindakan atau upaya yang dilakukan perusahaan…</p>\n', '2', '2246', 'publish', '2024-07-02 13:45:04', '2024-07-02 13:49:06', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2252', 'penandatanganan-perjanjian-kerja-sama-foshan-polytechnic-dan-pppvi-bpsdmi-kementerian-perindustrian-di-politeknik-stmi-jakarta', 'Penandatanganan Perjanjian Kerja Sama Foshan Polytechnic dan PPPVI BPSDMI Kementerian Perindustrian di Politeknik STMI Jakarta', '<p>Penandatanganan Perjanjian Kerja Sama antara Foshan Polytechnic dan Pusat Pengembangan Pendidikan Vokasi Industri BPSDMI Kementerian Perindustrian yang dilaksanakan di Ruang Rapat Politeknik STMI Jakarta pada Jumat, 28 Juni 2024.</p>\n<p><img fetchpriority=\"high\" fetchpriority=\"high\" decoding=\"async\" class=\"size-medium wp-image-2253 aligncenter\" src=\"{base_url}wp-content/uploads/2024/07/Picture1-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" srcset=\"{base_url}wp-content/uploads/2024/07/Picture1-300x225.jpg 300w, {base_url}wp-content/uploads/2024/07/Picture1-768x576.jpg 768w, {base_url}wp-content/uploads/2024/07/Picture1.jpg 924w\" sizes=\"(max-width: 300px) 100vw, 300px\" /></p>\n<p>Kegiatan penandatanganan perjanjian kerja sama diawali dengan sambutan dari Foshan Polythecnic oleh Mr. Zhao Yinsheng selaku Vice President Foshan Polytechnic.</p>\n<p><img decoding=\"async\" class=\"size-medium wp-image-2254 aligncenter\" src=\"{base_url}wp-content/uploads/2024/07/Picture2-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" srcset=\"{base_url}wp-content/uploads/2024/07/Picture2-300x225.jpg 300w, {base_url}wp-content/uploads/2024/07/Picture2.jpg 693w\" sizes=\"(max-width: 300px) 100vw, 300px\" /></p>\n<p>Selanjutnya, sambutan Kepala Pusat Pengembangan Pendidikan Vokasi Industri oleh Ibu Wulan Aprilianti Permata Sari</p>\n<p><img decoding=\"async\" class=\"size-medium wp-image-2255 aligncenter\" src=\"{base_url}wp-content/uploads/2024/07/Picture3-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" srcset=\"{base_url}wp-content/uploads/2024/07/Picture3-300x225.jpg 300w, {base_url}wp-content/uploads/2024/07/Picture3.jpg 693w\" sizes=\"(max-width: 300px) 100vw, 300px\" /></p>\n<p>Pada penandatangan kerja sama kemarin, ada beberapa rangkaian kegiatan yang diikuti oleh semua peserta meliputi Presentasi Profil Politeknik STMI Jakarta, Presentasi Hydrogen Energy Report dan Presentasi A Brief Introduction On Hydrogen Refueling Starion dari Foshan Polytechnic, serta kunjungan ke Workshop Politeknik STMI Jakarta.</p>\n<p>Kegiatan pertama yaitu pemaparan dan presentasi profil kampus Politeknik STMI Jakarta oleh Bapak Amrin Rapi, S.T., M.T selaku Direktur Politeknik STMI Jakarta.</p>\n<p style=\"text-align: center;\"><img loading=\"lazy\" loading=\"lazy\" decoding=\"async\" class=\"alignnone size-medium wp-image-2256\" src=\"{base_url}wp-content/uploads/2024/07/Picture4-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" srcset=\"{base_url}wp-content/uploads/2024/07/Picture4-300x225.jpg 300w, {base_url}wp-content/uploads/2024/07/Picture4.jpg 693w\" sizes=\"(max-width: 300px) 100vw, 300px\" /></p>\n<p>Kegiatan selanjutnya merupakan presentasi tentang Hydrogen Energy Report oleh Mr. Tang Rong dari Foshan Polytechnic.</p>\n<p><img loading=\"lazy\" loading=\"lazy\" decoding=\"async\" class=\"size-medium wp-image-2257 aligncenter\" src=\"{base_url}wp-content/uploads/2024/07/Picture5-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" srcset=\"{base_url}wp-content/uploads/2024/07/Picture5-300x225.jpg 300w, {base_url}wp-content/uploads/2024/07/Picture5.jpg 693w\" sizes=\"(max-width: 300px) 100vw, 300px\" /></p>\n<p>Selanjutnya, merupakan presentasi mengenai A Brief Introduction on Hydrogen Refueling Starion oleh Mr. Hu Wenyong dari Foshan Polytechnic.</p>\n<p><img loading=\"lazy\" loading=\"lazy\" decoding=\"async\" class=\"size-medium wp-image-2258 aligncenter\" src=\"{base_url}wp-content/uploads/2024/07/Picture6-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" srcset=\"{base_url}wp-content/uploads/2024/07/Picture6-300x225.jpg 300w, {base_url}wp-content/uploads/2024/07/Picture6.jpg 693w\" sizes=\"(max-width: 300px) 100vw, 300px\" /></p>\n<p>Setelah kegiatan pemaparan dan presentasi dari kedua kampus, maka dilanjutkan penandatanganan perjanjian kerja sama antara Pusat Pengembangan Pendidikan Vokasi Industri dan Foshan Polytechnic.</p>\n<p style=\"text-align: center;\"><img loading=\"lazy\" loading=\"lazy\" decoding=\"async\" class=\"alignnone size-medium wp-image-2259\" src=\"{base_url}wp-content/uploads/2024/07/Picture7-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" srcset=\"{base_url}wp-content/uploads/2024/07/Picture7-300x225.jpg 300w, {base_url}wp-content/uploads/2024/07/Picture7.jpg 693w\" sizes=\"(max-width: 300px) 100vw, 300px\" /></p>\n<p>Diakhir seluruh kegiatan, seluruh peserta melakukan kunjungan ke Workshop Politeknik STMI Jakarta.</p>\n<p><img loading=\"lazy\" loading=\"lazy\" decoding=\"async\" class=\"size-medium wp-image-2260 alignleft\" src=\"{base_url}wp-content/uploads/2024/07/Picture8-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" srcset=\"{base_url}wp-content/uploads/2024/07/Picture8-300x225.jpg 300w, {base_url}wp-content/uploads/2024/07/Picture8.jpg 693w\" sizes=\"(max-width: 300px) 100vw, 300px\" /> <img loading=\"lazy\" loading=\"lazy\" decoding=\"async\" class=\"size-medium wp-image-2261 alignright\" src=\"{base_url}wp-content/uploads/2024/07/Picture9-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" srcset=\"{base_url}wp-content/uploads/2024/07/Picture9-300x225.jpg 300w, {base_url}wp-content/uploads/2024/07/Picture9.jpg 693w\" sizes=\"(max-width: 300px) 100vw, 300px\" /> <img loading=\"lazy\" loading=\"lazy\" decoding=\"async\" class=\"size-medium wp-image-2262 aligncenter\" src=\"{base_url}wp-content/uploads/2024/07/Picture10-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" srcset=\"{base_url}wp-content/uploads/2024/07/Picture10-300x225.jpg 300w, {base_url}wp-content/uploads/2024/07/Picture10.jpg 693w\" sizes=\"(max-width: 300px) 100vw, 300px\" /></p>\n<p>&nbsp;</p>\n', '<p>Penandatanganan Perjanjian Kerja Sama antara Foshan Polytechnic dan Pusat Pengembangan Pendidikan Vokasi Industri BPSDMI Kementerian Perindustrian yang dilaksanakan di Ruang Rapat Politeknik STMI Jakarta pada Jumat, 28 Juni 2024. Kegiatan penandatanganan perjanjian kerja sama diawali dengan sambutan dari Foshan Polythecnic…</p>\n', '2', '2259', 'publish', '2024-07-02 16:32:49', '2024-07-03 07:56:36', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2270', 'penjajakan-kerja-sama-pt-adr-group-dengan-politeknik-stmi-jakarta', 'Penjajakan Kerja Sama PT ADR Group dengan Politeknik STMI Jakarta', '<p>Jakarta &#8211; PT ADR group melakukan kunjungan ke Politeknik STMI Jakarta dalam rangka penjajakan lanjutan untuk mengetahui dan mengenal fasilitas yang ada di Politeknik STMI Jakarta, Selasa (2/7/2024).</p>\n<p><img fetchpriority=\"high\" fetchpriority=\"high\" decoding=\"async\" class=\"size-medium wp-image-2266 aligncenter\" src=\"{base_url}wp-content/uploads/2024/07/Picture11-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" srcset=\"{base_url}wp-content/uploads/2024/07/Picture11-300x225.jpg 300w, {base_url}wp-content/uploads/2024/07/Picture11-1024x768.jpg 1024w, {base_url}wp-content/uploads/2024/07/Picture11-768x576.jpg 768w, {base_url}wp-content/uploads/2024/07/Picture11-1536x1152.jpg 1536w, {base_url}wp-content/uploads/2024/07/Picture11.jpg 1600w\" sizes=\"(max-width: 300px) 100vw, 300px\" /></p>\n<p>Personel dari PT ADR Group yang hadir yaitu HR Manager (Emilia Sari) dan staff HR (Hadi Priyanto, Ilham). Diskusi pokok yang dilakukan terkait dengan penyelenggaraan penempatan prakerin, perekrutan lulusan Politeknik STMI Jakarta dan program pendidikan D1 Industri.</p>\n<p>&nbsp;</p>\n<p>Kedatangan PT. ADR Group disambut baik oleh Politeknik STMI Jakarta. Direktur Politeknik STMI Jakarta Bapak Amrin Rapi mempresentasikan Profil Politeknik STMI Jakarta. “Saya mendukung penuh kerja sama Politeknik STMI Jakarta dengan industri dan mengharapkan serapan lulusan naik serta lulusan STMI sebelum wisuda sudah di rekrut oleh industri” ujar Amrin Rapi</p>\n<p>&nbsp;</p>\n<p>Selain itu, juga PT ADR Group melakukan kunjungan ke laboratorium yang ada di Politeknik STMI Jakarta untuk mendapatkan gambaran sarana dan prasarana penunjang pendidikan yang ada.</p>\n<p><img decoding=\"async\" class=\"size-medium wp-image-2267 aligncenter\" src=\"{base_url}wp-content/uploads/2024/07/Picture12-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" srcset=\"{base_url}wp-content/uploads/2024/07/Picture12-300x225.jpg 300w, {base_url}wp-content/uploads/2024/07/Picture12-1024x768.jpg 1024w, {base_url}wp-content/uploads/2024/07/Picture12-768x576.jpg 768w, {base_url}wp-content/uploads/2024/07/Picture12-1536x1152.jpg 1536w, {base_url}wp-content/uploads/2024/07/Picture12.jpg 1600w\" sizes=\"(max-width: 300px) 100vw, 300px\" /></p>\n<p><img decoding=\"async\" class=\"size-medium wp-image-2268 aligncenter\" src=\"{base_url}wp-content/uploads/2024/07/Picture13-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" srcset=\"{base_url}wp-content/uploads/2024/07/Picture13-300x225.jpg 300w, {base_url}wp-content/uploads/2024/07/Picture13-1024x768.jpg 1024w, {base_url}wp-content/uploads/2024/07/Picture13-768x576.jpg 768w, {base_url}wp-content/uploads/2024/07/Picture13-1536x1152.jpg 1536w, {base_url}wp-content/uploads/2024/07/Picture13.jpg 1600w\" sizes=\"(max-width: 300px) 100vw, 300px\" /></p>\n<p>&nbsp;</p>\n', '<p>Jakarta &#8211; PT ADR group melakukan kunjungan ke Politeknik STMI Jakarta dalam rangka penjajakan lanjutan untuk mengetahui dan mengenal fasilitas yang ada di Politeknik STMI Jakarta, Selasa (2/7/2024). Personel dari PT ADR Group yang hadir yaitu HR Manager (Emilia Sari)…</p>\n', '2', '2266', 'publish', '2024-07-03 08:07:40', '2024-07-03 08:10:22', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2272', 'perpanjangan-penandatangan-mou-antara-politeknik-stmi-jakarta-dengan-pt-denso-indonesia', 'Perpanjangan Penandatangan MoU antara Politeknik STMI Jakarta dengan PT. Denso Indonesia', '<p>Halo Sobat STMI!</p>\n<p>&nbsp;</p>\n<p>Pada hari ini, Rabu 3 Juli 2024 telah dilaksanakan Perpanjangan Penandatangan MoU antara Politeknik STMI Jakarta dengan PT. Denso Indonesia dan disaksikan oleh Sekretaris BPSDMI</p>\n<p><img fetchpriority=\"high\" fetchpriority=\"high\" decoding=\"async\" class=\"size-medium wp-image-2273 aligncenter\" src=\"{base_url}wp-content/uploads/2024/07/Picture14-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" srcset=\"{base_url}wp-content/uploads/2024/07/Picture14-300x225.jpg 300w, {base_url}wp-content/uploads/2024/07/Picture14-1024x768.jpg 1024w, {base_url}wp-content/uploads/2024/07/Picture14-768x576.jpg 768w, {base_url}wp-content/uploads/2024/07/Picture14-1536x1152.jpg 1536w, {base_url}wp-content/uploads/2024/07/Picture14-2048x1536.jpg 2048w\" sizes=\"(max-width: 300px) 100vw, 300px\" /></p>\n<p>Penandatangan Mou dilakukan oleh Direktur Politeknik STMI, Bapak Amrin Rapi dengan Direktur HR PT Denso Indonesia, Bapak Subrono dan disaksikan oleh Sekretaris BPSDMI, Bapak Jonni Afrizon</p>\n<p><img decoding=\"async\" class=\"size-medium wp-image-2275 aligncenter\" src=\"{base_url}wp-content/uploads/2024/07/Picture16-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" srcset=\"{base_url}wp-content/uploads/2024/07/Picture16-300x225.jpg 300w, {base_url}wp-content/uploads/2024/07/Picture16-1024x768.jpg 1024w, {base_url}wp-content/uploads/2024/07/Picture16-768x576.jpg 768w, {base_url}wp-content/uploads/2024/07/Picture16-1536x1152.jpg 1536w, {base_url}wp-content/uploads/2024/07/Picture16-2048x1536.jpg 2048w\" sizes=\"(max-width: 300px) 100vw, 300px\" /></p>\n<p>Semoga kolaborasi antara Politeknik STMI Jakarta dengan PT. Denso Indonesia terjalin dengan baik</p>\n<p><img decoding=\"async\" class=\"size-medium wp-image-2274 aligncenter\" src=\"{base_url}wp-content/uploads/2024/07/Picture15-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" srcset=\"{base_url}wp-content/uploads/2024/07/Picture15-300x225.jpg 300w, {base_url}wp-content/uploads/2024/07/Picture15-1024x768.jpg 1024w, {base_url}wp-content/uploads/2024/07/Picture15-768x576.jpg 768w, {base_url}wp-content/uploads/2024/07/Picture15-1536x1152.jpg 1536w, {base_url}wp-content/uploads/2024/07/Picture15-2048x1536.jpg 2048w\" sizes=\"(max-width: 300px) 100vw, 300px\" /></p>\n<p>—————————</p>\n<p>Join us 📲</p>\n<p>Website : www.stmi.ac.id</p>\n<p>IG: @stmijakarta</p>\n<p>Twitter: @stmijakarta</p>\n<p>Facebook: Politeknik STMI Jakarta</p>\n<p>WA : 085155244455</p>\n<p>—————————</p>\n<p>Kementerian Perindustrian RI</p>\n<p>#politeknikstmijakarta</p>\n<p>#Politeknik</p>\n<p>#STMIJakarta</p>\n<p>#STMIWBK</p>\n', '<p>Halo Sobat STMI! &nbsp; Pada hari ini, Rabu 3 Juli 2024 telah dilaksanakan Perpanjangan Penandatangan MoU antara Politeknik STMI Jakarta dengan PT. Denso Indonesia dan disaksikan oleh Sekretaris BPSDMI Penandatangan Mou dilakukan oleh Direktur Politeknik STMI, Bapak Amrin Rapi dengan…</p>\n', '2', '2274', 'publish', '2024-07-04 08:10:44', '2024-07-04 08:15:40', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2287', 'pencetakan-kartu-ujian-akhir-semester-uas-semester-genap-tahun-akademik-2023-2024', 'Pencetakan Kartu Ujian Akhir Semester (UAS) Semester Genap Tahun Akademik 2023/2024', '<p>Kepada mahasiswa/i Politeknik STMI Jakarta</p>\n<p>Berikut dibawah ini terlampir Pengumuman Pencetakan Kartu Ujian Akhir Semester (UAS) Semester Genap Tahun Akademik 2023/2024</p>\n<p>Mohon untuk dibaca dengan seksama, Terimakasih</p>\n<p>&nbsp;</p>\n<a href=\"{base_url}wp-content/uploads/2024/07/Pencetakan-Kartu-UAS-genap-2024.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">Pencetakan Kartu UAS genap 2024</a>\n', '<p>Kepada mahasiswa/i Politeknik STMI Jakarta Berikut dibawah ini terlampir Pengumuman Pencetakan Kartu Ujian Akhir Semester (UAS) Semester Genap Tahun Akademik 2023/2024 Mohon untuk dibaca dengan seksama, Terimakasih &nbsp;</p>\n', '2', '190', 'publish', '2024-07-11 10:29:21', '2024-07-11 10:46:20', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2291', 'pengumuman-tata-tertib-ujian-akhir-semester-genap-tahun-akademik-2023-2024', 'Pengumuman Tata Tertib Ujian Akhir Semester Genap Tahun Akademik 2023/2024', '<p style=\"margin: 0cm; background: white;\"><span style=\"font-family: \'Arial\',sans-serif; color: black;\">Kepada mahasiswa/i Politeknik STMI Jakarta </span></p>\n<p style=\"margin: 0cm; background: white;\"><span style=\"font-family: \'Arial\',sans-serif; color: black;\">Berikut dibawah ini terlampir Pengumuman Tata Tertib Ujian Akhir Semester Genap Tahun Akademik 2023/2024</span></p>\n<p style=\"margin: 0cm; background: white;\"><span style=\"font-family: \'Arial\',sans-serif; color: black;\">Mohon dibaca dengan seksama, Terimakasih</span></p>\n<p>&nbsp;</p>\n<a href=\"{base_url}wp-content/uploads/2024/07/2024-Tata-Tertib-UAS-2024.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">2024 Tata Tertib UAS 2024</a>\n', '<p>Kepada mahasiswa/i Politeknik STMI Jakarta Berikut dibawah ini terlampir Pengumuman Tata Tertib Ujian Akhir Semester Genap Tahun Akademik 2023/2024 Mohon dibaca dengan seksama, Terimakasih &nbsp;</p>\n', '2', '190', 'publish', '2024-07-11 10:45:36', '2024-07-11 11:11:15', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2295', 'jadwal-ujian-akhir-semester-genap-tahun-akademik-2023-2024', 'Jadwal Ujian Akhir Semester Genap Tahun Akademik 2023/2024', '<p style=\"margin-top: 0cm;\"><span style=\"font-family: \'Arial\',sans-serif; color: black;\">Kepada Yth, Bapak/ibu dosen dan mahasiswa Politeknik STMI Jakarta</span></p>\n<p style=\"margin-top: 0cm; box-sizing: border-box; margin-bottom: var(--theme-content-spacing); font-variant-ligatures: normal; font-variant-caps: normal; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-stretch: inherit; line-height: inherit; font-optical-sizing: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; margin-inline: var(--theme-default-editor, auto); max-width: var(--theme-default-editor, var(--theme-block-max-width)); width: var(--theme-default-editor, var(--theme-block-width)); orphans: 2; text-align: start; widows: 2; -webkit-text-stroke-width: 0px; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; word-spacing: 0px;\"><span style=\"font-family: \'Arial\',sans-serif; color: black;\">Berikut dibawah ini terlampir Jadwal Ujian Akhir Semester Genap Tahun Akademik 2023/2024</span></p>\n<p><span style=\"font-family: \'Arial\',sans-serif; color: black;\">Terimakasih</span></p>\n<p style=\"margin-top: 0cm; box-sizing: border-box; margin-bottom: var(--theme-content-spacing); font-variant-ligatures: normal; font-variant-caps: normal; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-stretch: inherit; line-height: inherit; font-optical-sizing: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; margin-inline: var(--theme-default-editor, auto); max-width: var(--theme-default-editor, var(--theme-block-max-width)); width: var(--theme-default-editor, var(--theme-block-width)); orphans: 2; text-align: start; widows: 2; -webkit-text-stroke-width: 0px; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; word-spacing: 0px;\"><span style=\"font-family: \'Arial\',sans-serif; color: black;\"><a href=\"{base_url}wp-content/uploads/2024/07/Jadwal-UAS-Genap-2023-2024.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">Jadwal UAS Genap 2023-2024</a></span></p>\n', '<p>Kepada Yth, Bapak/ibu dosen dan mahasiswa Politeknik STMI Jakarta Berikut dibawah ini terlampir Jadwal Ujian Akhir Semester Genap Tahun Akademik 2023/2024 Terimakasih</p>\n', '2', '190', 'publish', '2024-07-11 10:50:45', '2024-07-11 10:50:45', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2297', 'penjajakan-kerja-sama-pt-kencana-panelindo-dengan-politeknik-stmi-jakarta', 'Penjajakan Kerja Sama PT Kencana Panelindo dengan Politeknik STMI Jakarta', '<p>Pada hari Selasa 9 Juli 2024 telah dilaksanakan Penjajakan Kerja Sama PT Kencana Panelindo dengan Politeknik STMI Jakarta dalam hal Kerja Sama Penelitian</p>\n<p><img fetchpriority=\"high\" fetchpriority=\"high\" decoding=\"async\" class=\"aligncenter wp-image-2298 size-large\" src=\"{base_url}wp-content/uploads/2024/07/Picture-17-1024x768.jpg\" alt=\"\" width=\"1024\" height=\"768\" srcset=\"{base_url}wp-content/uploads/2024/07/Picture-17-1024x768.jpg 1024w, {base_url}wp-content/uploads/2024/07/Picture-17-300x225.jpg 300w, {base_url}wp-content/uploads/2024/07/Picture-17-768x576.jpg 768w, {base_url}wp-content/uploads/2024/07/Picture-17-1536x1152.jpg 1536w, {base_url}wp-content/uploads/2024/07/Picture-17.jpg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></p>\n<p>Semoga ini awal kolaborasi yang baik antara Politeknik STMI Jakarta dengan PT Kencana Panelindo</p>\n<p><img decoding=\"async\" class=\"aligncenter wp-image-2299 size-large\" src=\"{base_url}wp-content/uploads/2024/07/Picture-19-1024x768.jpg\" alt=\"\" width=\"1024\" height=\"768\" srcset=\"{base_url}wp-content/uploads/2024/07/Picture-19-1024x768.jpg 1024w, {base_url}wp-content/uploads/2024/07/Picture-19-300x225.jpg 300w, {base_url}wp-content/uploads/2024/07/Picture-19-768x576.jpg 768w, {base_url}wp-content/uploads/2024/07/Picture-19-1536x1152.jpg 1536w, {base_url}wp-content/uploads/2024/07/Picture-19-2048x1536.jpg 2048w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></p>\n<p>——————————————————————————————————————————————————————</p>\n<p>Join us 📲</p>\n<p>Website : www.stmi.ac.id</p>\n<p>IG: @stmijakarta</p>\n<p>Twitter: @stmijakarta</p>\n<p>Facebook: Politeknik STMI Jakarta</p>\n<p>WA : 085155244455</p>\n<p>—————————</p>\n<p>Kementerian Perindustrian RI</p>\n<p>#politeknikstmijakarta</p>\n<p>#Politeknik</p>\n<p>#STMIJakarta</p>\n<p>#STMIWBK</p>\n<p>#STMIMenujuWBBM</p>\n<p>#Kampus</p>\n<p>#VokasiKompeten</p>\n<p>#SobatIndustri</p>\n<p>#JoinSTMI</p>\n', '<p>Pada hari Selasa 9 Juli 2024 telah dilaksanakan Penjajakan Kerja Sama PT Kencana Panelindo dengan Politeknik STMI Jakarta dalam hal Kerja Sama Penelitian Semoga ini awal kolaborasi yang baik antara Politeknik STMI Jakarta dengan PT Kencana Panelindo —————————————————————————————————————————————————————— Join us…</p>\n', '2', '2298', 'publish', '2024-07-11 11:07:44', '2024-07-15 10:13:41', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2310', 'pengumuman-pendaftaran-yudisium-tahap-1-politeknik-stmi-jakarta', 'Pengumuman Pendaftaran Yudisium Tahap 1 Politeknik STMI Jakarta', '<p style=\"margin-top: 0cm;\"><span style=\"font-family: \'Arial\',sans-serif; color: black;\">Kepada seluruh Mahasiswa/i yang telah lulus sidang akhir.</span></p>\n<p style=\"margin-top: 0cm; box-sizing: border-box; margin-bottom: var(--theme-content-spacing); font-variant-ligatures: normal; font-variant-caps: normal; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-stretch: inherit; line-height: inherit; font-optical-sizing: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; margin-inline: var(--theme-default-editor, auto); max-width: var(--theme-default-editor, var(--theme-block-max-width)); width: var(--theme-default-editor, var(--theme-block-width)); orphans: 2; text-align: start; widows: 2; -webkit-text-stroke-width: 0px; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; word-spacing: 0px;\"><span style=\"font-family: \'Arial\',sans-serif; color: black;\">Harap menjadi perhatian dan mendownload pengumumannya di bawah ini.</span></p>\n<p>&nbsp;</p>\n<a href=\"{base_url}wp-content/uploads/2024/07/2024-Nomor-2287_pengumuman-Yudisium-1.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">2024 Nomor 2287_pengumuman Yudisium 1</a>\n', '<p>Kepada seluruh Mahasiswa/i yang telah lulus sidang akhir. Harap menjadi perhatian dan mendownload pengumumannya di bawah ini. &nbsp;</p>\n', '2', '190', 'publish', '2024-07-23 15:19:04', '2024-07-23 15:19:24', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2312', 'penjajakan-kerjasama-antara-politeknik-stmi-jakarta-dengan-s4c-dan-swisscham', 'Penjajakan Kerjasama antara Politeknik STMI Jakarta dengan S4C dan SwissCham', '<p>Pada hari, Kamis 25 Juli 2024 telah dilaksanakan Penjajakan kedua untuk teknis Kerjasama antara Politeknik STMI Jakarta dengan S4C dan SwissCham.</p>\n<p><img fetchpriority=\"high\" fetchpriority=\"high\" decoding=\"async\" class=\"size-medium wp-image-2313 aligncenter\" src=\"{base_url}wp-content/uploads/2024/07/Picture-21-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" srcset=\"{base_url}wp-content/uploads/2024/07/Picture-21-300x225.jpg 300w, {base_url}wp-content/uploads/2024/07/Picture-21-1024x768.jpg 1024w, {base_url}wp-content/uploads/2024/07/Picture-21-768x576.jpg 768w, {base_url}wp-content/uploads/2024/07/Picture-21-1536x1152.jpg 1536w, {base_url}wp-content/uploads/2024/07/Picture-21-2048x1536.jpg 2048w\" sizes=\"(max-width: 300px) 100vw, 300px\" /></p>\n<p>Agenda yang dilakukan pembahasan mengenai Penandatanganan MoU, penyerapan mahasiswa prakerin 1 tahun pada perusahaan Swiss di Indonesia.</p>\n', '<p>Pada hari, Kamis 25 Juli 2024 telah dilaksanakan Penjajakan kedua untuk teknis Kerjasama antara Politeknik STMI Jakarta dengan S4C dan SwissCham. Agenda yang dilakukan pembahasan mengenai Penandatanganan MoU, penyerapan mahasiswa prakerin 1 tahun pada perusahaan Swiss di Indonesia.</p>\n', '2', '2313', 'publish', '2024-07-26 13:59:04', '2024-07-26 13:59:04', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2323', 'pengumuman-pelaksanaan-yudisium-i', 'Pengumuman Pelaksanaan Yudisium I', '<p>Diberitahukan kepada seluruh Mahasiswa/i Tingkat Akhir Politeknik STMI Jakarta yang telah lulus sidang tugas akhir.</p>\n<p>Harap menjadi perhatian dan mendownload pengumumannya di bawah ini.</p>\n<a href=\"{base_url}wp-content/uploads/2024/08/2024-Nomor-2543-pengumuman-Peserta-Yudisium-1.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">2024 Nomor 2543 pengumuman Peserta Yudisium 1</a>\n', '<p>Diberitahukan kepada seluruh Mahasiswa/i Tingkat Akhir Politeknik STMI Jakarta yang telah lulus sidang tugas akhir. Harap menjadi perhatian dan mendownload pengumumannya di bawah ini.</p>\n', '2', '190', 'publish', '2024-08-01 10:38:57', '2024-08-01 10:58:09', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2327', 'pengumuman-awal-semester-ganjil-tahun-akademik-2024-2025', 'Pengumuman Awal Semester Ganjil Tahun Akademik 2024/2025', '<p>Diberitahukan kepada civitas akademika Politeknik STMI Jakarta.</p>\n<p>Harap menjadi perhatian dan terima kasih</p>\n<a href=\"{base_url}wp-content/uploads/2024/08/No-Surat-2285-Pengumuman-Awal-Perkuliahan-Ganjil.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">No Surat 2285 Pengumuman Awal Perkuliahan Ganjil</a>\n', '<p>Diberitahukan kepada civitas akademika Politeknik STMI Jakarta. Harap menjadi perhatian dan terima kasih</p>\n', '2', '190', 'publish', '2024-08-01 10:57:06', '2024-08-01 10:57:06', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2331', 'pelaksanaan-pelatihan-lemmi-4-0-politeknik-stmi-jakarta', 'Pelaksanaan Pelatihan Lemmi 4.0 Politeknik STMI Jakarta', '<p>Halo Sobat STMI!  Pada hari ini, Kamis 1 Agustus 2024 telah dilaksanakan pelatihan Lemmi 4.0 Politeknik STMI Jakarta yang diikuti oleh mahasiswa tahun 2024.</p>\n<p>1. Pelatihan Lemmi 4.0 untuk Mahasiswa Tahun 2024 Politeknik STMI Jakarta</p>\n<p><img fetchpriority=\"high\" fetchpriority=\"high\" decoding=\"async\" class=\"size-medium wp-image-2332 aligncenter\" src=\"{base_url}wp-content/uploads/2024/08/Picture-23-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" srcset=\"{base_url}wp-content/uploads/2024/08/Picture-23-300x225.jpg 300w, {base_url}wp-content/uploads/2024/08/Picture-23-1024x768.jpg 1024w, {base_url}wp-content/uploads/2024/08/Picture-23-768x576.jpg 768w, {base_url}wp-content/uploads/2024/08/Picture-23-1536x1152.jpg 1536w, {base_url}wp-content/uploads/2024/08/Picture-23.jpg 1600w\" sizes=\"(max-width: 300px) 100vw, 300px\" /></p>\n<p>2. Pelaksanaan Pelatihan Lemmi 4.0 untuk Mahasiswa Tahun 2024 Politeknik STMI Jakarta</p>\n<p><img decoding=\"async\" class=\"size-medium wp-image-2333 aligncenter\" src=\"{base_url}wp-content/uploads/2024/08/Picture-24-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" srcset=\"{base_url}wp-content/uploads/2024/08/Picture-24-300x225.jpg 300w, {base_url}wp-content/uploads/2024/08/Picture-24-1024x768.jpg 1024w, {base_url}wp-content/uploads/2024/08/Picture-24-768x576.jpg 768w, {base_url}wp-content/uploads/2024/08/Picture-24.jpg 1280w\" sizes=\"(max-width: 300px) 100vw, 300px\" /></p>\n<p>3. Pelatihan LeMMI 4.0 untuk Mahasiswa Tahun 2024 terkait KPI OEE oleh Sensei Yoshiro Fukuda (Profesor Emeritus, Hosel University Jepang)</p>\n<p><img decoding=\"async\" class=\"size-medium wp-image-2334 aligncenter\" src=\"{base_url}wp-content/uploads/2024/08/Picture-25-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" srcset=\"{base_url}wp-content/uploads/2024/08/Picture-25-300x225.jpg 300w, {base_url}wp-content/uploads/2024/08/Picture-25-1024x768.jpg 1024w, {base_url}wp-content/uploads/2024/08/Picture-25-768x576.jpg 768w, {base_url}wp-content/uploads/2024/08/Picture-25.jpg 1280w\" sizes=\"(max-width: 300px) 100vw, 300px\" /></p>\n<p>4. Plarail Exercise dalam Pelatihan LeMMI 4.0 Mahasiswa Tahun 2024 Politeknik STMI Jakarta</p>\n<p><img loading=\"lazy\" loading=\"lazy\" decoding=\"async\" class=\"size-medium wp-image-2335 aligncenter\" src=\"{base_url}wp-content/uploads/2024/08/Picture-26-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" srcset=\"{base_url}wp-content/uploads/2024/08/Picture-26-300x225.jpg 300w, {base_url}wp-content/uploads/2024/08/Picture-26-1024x768.jpg 1024w, {base_url}wp-content/uploads/2024/08/Picture-26-768x576.jpg 768w, {base_url}wp-content/uploads/2024/08/Picture-26.jpg 1280w\" sizes=\"(max-width: 300px) 100vw, 300px\" /></p>\n', '<p>Halo Sobat STMI!  Pada hari ini, Kamis 1 Agustus 2024 telah dilaksanakan pelatihan Lemmi 4.0 Politeknik STMI Jakarta yang diikuti oleh mahasiswa tahun 2024. 1. Pelatihan Lemmi 4.0 untuk Mahasiswa Tahun 2024 Politeknik STMI Jakarta 2. Pelaksanaan Pelatihan Lemmi 4.0…</p>\n', '2', '2332', 'publish', '2024-08-01 16:05:41', '2024-08-01 16:14:17', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2341', 'pengumuman-perubahan-jadwal-pembayaran', 'Pengumuman Perubahan Jadwal Pembayaran', '<p>Kepada mahasiswa/i Politeknik STMI Jakarta</p>\n<p>Berikut dibawah ini terlampir Pengumuman Perubahan Jadwal Pembayaran SPP/Sidang/Cuti Akademik/Uji Kompetensi  dan Proses Perubahan Nomor Rekening Politeknik STMI Jakarta</p>\n<p>Mohon dibaca dengan seksama, Terimakasih</p>\n<p>&nbsp;</p>\n<a href=\"{base_url}wp-content/uploads/2024/08/Pengumuman-Perubahan-Jadwal-Pembayaran.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">Pengumuman Perubahan Jadwal Pembayaran</a>\n', '<p>Kepada mahasiswa/i Politeknik STMI Jakarta Berikut dibawah ini terlampir Pengumuman Perubahan Jadwal Pembayaran SPP/Sidang/Cuti Akademik/Uji Kompetensi  dan Proses Perubahan Nomor Rekening Politeknik STMI Jakarta Mohon dibaca dengan seksama, Terimakasih &nbsp;</p>\n', '2', '190', 'publish', '2024-08-22 11:19:15', '2024-08-22 11:19:26', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2345', 'kalender-akademik-politeknik-stmi-jakarta-t-a-2024-2025', 'Kalender Akademik Politeknik STMI Jakarta T.A. 2024/2025', '<p>Kepada seluruh Mahasiswa/i Politeknik STMI Jakarta,</p>\n<p>Berikut di bawah ini terlampir kalender akademik Politeknik STMI Jakarta T.A. 2024/2025,</p>\n<p>&nbsp;</p>\n<p>mohon untuk di baca dengan seksama. Terima kasih.</p>\n[wpdm_package id=\'2346\']\n', '<p>Kepada seluruh Mahasiswa/i Politeknik STMI Jakarta, Berikut di bawah ini terlampir kalender akademik Politeknik STMI Jakarta T.A. 2024/2025, &nbsp; mohon untuk di baca dengan seksama. Terima kasih.</p>\n', '1', '779', 'publish', '2024-08-27 14:25:35', '2024-08-27 14:26:32', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2368', 'pengumuman-beauty-contest', 'Pengumuman Beauty Contest', '<p>Berdasarkan Surat Keputusan Menteri Keuangan Republik Indonesia Nomor 334 Tahun 2024 Tanggal 19 Agustus 2024 yang menyatakan bahwa Politeknik STMI Jakarta ditetapkan sebagai Instansi Pemerintah yang menerapkan Pola Pengelolaan Keuangan Badan Layanan Umum (PPK – BLU), maka salah satu tindak lanjutnya Politeknik STMI Jakarta mengadakan “Beauty Contest” Pemilihan Bank Mitra sebagai partner dalam Pengelolaan Keuangan BLU. Panitia Pemilihan Bank Mitra pada Badan Layanan Umum (BLU) Politeknik STMI Jakarta akan melaksanakan Beauty Contest Pemilihan Bank Mitra Kerjasama, selengkapnya dapat dilihat pada Pengumuman dan Dokumen Pemilihan terlampir.</p>\n<p>Terimakasih</p>\n<p>&nbsp;</p>\n<a href=\"{base_url}wp-content/uploads/2024/08/Dokumen-Pemilihan-dan-KAK-Beauty-Contest-Politeknik-STMI-Jakarta-3.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">Dokumen Pemilihan dan KAK Beauty Contest Politeknik STMI Jakarta</a>\n<a href=\"{base_url}wp-content/uploads/2024/08/Pengumuman-Beauty-Contest-3.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">Pengumuman Beauty Contest</a>\n', '<p>Berdasarkan Surat Keputusan Menteri Keuangan Republik Indonesia Nomor 334 Tahun 2024 Tanggal 19 Agustus 2024 yang menyatakan bahwa Politeknik STMI Jakarta ditetapkan sebagai Instansi Pemerintah yang menerapkan Pola Pengelolaan Keuangan Badan Layanan Umum (PPK – BLU), maka salah satu tindak…</p>\n', '2', '452', 'publish', '2024-08-28 15:47:23', '2024-08-28 15:47:23', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2378', 'ketentuan-pakaian-mahasiswa-baru-angkatan-2024', 'Ketentuan Pakaian Mahasiswa Baru Angkatan 2024', '<p>Kepada mahasiswa/i baru Politeknik STMI Jakarta Angkatan 2024</p>\n<p>Berikut dibawah ini terlampir Pengumuman Ketentuan Pakaian Mahasiswa Baru Angkatan 2024 Politeknik STMI Jakarta</p>\n<p>Mohon dibaca dengan seksama, Terimakasih</p>\n<p><a href=\"{base_url}wp-content/uploads/2024/08/No-Surat-3141-Pengumuman-Ketentuan-pakaian-baru-MABA.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">No Surat 3141 Pengumuman Ketentuan pakaian baru MABA</a><a href=\"{base_url}wp-content/uploads/2024/08/No-Surat-3141-Pengumuman-Ketentuan-pakaian-baru-MABA.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">No Surat 3141 Pengumuman Ketentuan pakaian baru MABA</a></p>\n<p>&nbsp;</p>\n', '<p>Kepada mahasiswa/i baru Politeknik STMI Jakarta Angkatan 2024 Berikut dibawah ini terlampir Pengumuman Ketentuan Pakaian Mahasiswa Baru Angkatan 2024 Politeknik STMI Jakarta Mohon dibaca dengan seksama, Terimakasih &nbsp;</p>\n', '2', '2377', 'publish', '2024-08-29 16:29:23', '2024-08-29 16:29:23', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2385', 'penandatanganan-pks-antara-pt-astra-daido-steel-indonesia-dengan-politeknik-stmi-jakarta-terkait-kerja-sama-pelaksanaan-pendidikan-dual-sistem-dalam-praktik-kerja-industri-prakerin', 'Penandatanganan PKS antara PT Astra Daido Steel Indonesia dengan Politeknik STMI Jakarta', '<p>Pada hari, Kamis 29 Agustus 2024 telah dilaksanakan Penandatanganan PKS antara PT Astra Daido Steel Indonesia dengan Politeknik STMI Jakarta terkait Kerja Sama Pelaksanaan Pendidikan Dual-Sistem dalam Praktik Kerja Industri (Prakerin).</p>\n<p>Semoga kerjasama antara Politeknik STMI Jakarta dengan PT Astra Daido Steel Indonesia terjalin dengan baik.</p>\n<p><img fetchpriority=\"high\" fetchpriority=\"high\" decoding=\"async\" class=\"size-medium wp-image-2386 aligncenter\" src=\"{base_url}wp-content/uploads/2024/08/Picture-27-300x169.jpg\" alt=\"\" width=\"300\" height=\"169\" srcset=\"{base_url}wp-content/uploads/2024/08/Picture-27-300x169.jpg 300w, {base_url}wp-content/uploads/2024/08/Picture-27-1024x576.jpg 1024w, {base_url}wp-content/uploads/2024/08/Picture-27-768x432.jpg 768w, {base_url}wp-content/uploads/2024/08/Picture-27-1536x864.jpg 1536w, {base_url}wp-content/uploads/2024/08/Picture-27-2048x1152.jpg 2048w\" sizes=\"(max-width: 300px) 100vw, 300px\" /></p>\n', '<p>Pada hari, Kamis 29 Agustus 2024 telah dilaksanakan Penandatanganan PKS antara PT Astra Daido Steel Indonesia dengan Politeknik STMI Jakarta terkait Kerja Sama Pelaksanaan Pendidikan Dual-Sistem dalam Praktik Kerja Industri (Prakerin). Semoga kerjasama antara Politeknik STMI Jakarta dengan PT Astra…</p>\n', '2', '2387', 'publish', '2024-08-29 16:48:03', '2024-08-29 16:49:56', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2396', 'rapat-kerja-politeknik-stmi-jakarta-tahun-2024', 'Rapat Kerja Politeknik STMI Jakarta Tahun 2024', '<p>Pada tanggal  26 &#8211; 28 Februari 2024, Politeknik STMI Jakarta menggelar Rapat Kerja Tahunan yang menjadi ajang strategis bagi seluruh pimpinan unit, dosen, dan staf untuk merumuskan arah kebijakan dan program kerja yang akan dilaksanakan di tahun mendatang. Rapat kerja kali ini tidak hanya fokus pada upaya adaptasi terhadap tantangan Revolusi Industri 4.0, tetapi juga pada peningkatan akuntabilitas kinerja institusi melalui penerapan Perjanjian Kinerja (Perkin).</p>\n<p><strong>Sosialisasi TVET 4.0: Menyongsong Era Industri 4.0</strong></p>\n<p>Dalam agenda pertama, para peserta rapat kerja disuguhkan dengan <strong>Sosialisasi TVET 4.0</strong> (Technical and Vocational Education and Training). Konsep TVET 4.0 ini merupakan respons terhadap perkembangan teknologi yang cepat di era Industri 4.0, yang ditandai dengan kemajuan di bidang otomatisasi, kecerdasan buatan, dan konektivitas digital. Sosialisasi ini bertujuan untuk membekali seluruh sivitas akademika dengan pemahaman mendalam tentang bagaimana pendidikan vokasi harus bertransformasi agar tetap relevan dan mampu mencetak lulusan yang siap bersaing di pasar kerja global.</p>\n<p>Materi sosialisasi disampaikan oleh Direktur, yang membahas berbagai pendekatan baru dalam proses pembelajaran, seperti integrasi teknologi terbaru dalam kurikulum, pengembangan kompetensi digital, serta peningkatan kolaborasi dengan dunia usaha. Diskusi mendalam juga dilakukan untuk merumuskan strategi implementasi TVET 4.0 di Politeknik STMI Jakarta, termasuk penguatan fasilitas laboratorium dan program magang berbasis industri 4.0.</p>\n<p><strong>Sosialisasi Perjanjian Kinerja (Perkin): Mengoptimalkan Kinerja dan Akuntabilitas</strong></p>\n<p>Selanjutnya, agenda rapat kerja dilanjutkan dengan <strong>Sosialisasi Perjanjian Kinerja (Perkin)</strong>. Perkin merupakan salah satu instrumen penting dalam manajemen kinerja di lingkungan Politeknik STMI Jakarta, yang bertujuan untuk memastikan setiap unit kerja memiliki sasaran kinerja yang jelas, terukur, dan selaras dengan visi serta misi institusi. Dalam sosialisasi ini, para peserta diberikan pemahaman mengenai pentingnya perencanaan kinerja yang sistematis, serta bagaimana melakukan monitoring dan evaluasi terhadap pencapaian kinerja secara berkala.</p>\n<p>Sosialisasi Perkin juga menekankan pada peningkatan akuntabilitas di setiap level organisasi, dimana setiap pimpinan unit diharapkan mampu menerjemahkan sasaran kinerja yang telah disepakati ke dalam program-program kerja yang efektif dan efisien. Dengan demikian, Politeknik STMI Jakarta dapat terus meningkatkan kualitas layanan pendidikan dan manajemen, serta mencapai target-target strategis yang telah ditetapkan.</p>\n<p><strong>Kesimpulan dan Harapan</strong></p>\n<p>Rapat kerja ini diharapkan dapat menjadi momentum bagi Politeknik STMI Jakarta untuk terus berinovasi dan beradaptasi dalam menghadapi tantangan masa depan. Dengan implementasi TVET 4.0 yang efektif dan penerapan Perjanjian Kinerja yang optimal, Politeknik STMI Jakarta siap untuk mencetak lulusan yang kompeten, unggul, dan mampu berkontribusi dalam pembangunan industri nasional dan internasional</p>\n<p>&nbsp;</p>\n<p>#politeknikstmijakarta<br />\n#Politeknik<br />\n#STMIJakarta<br />\n#STMIWBK<br />\n#STMIMenujuWBBM<br />\n#Kampus<br />\n#VokasiKompeten<br />\n#SobatIndustri<br />\n#JoinSTMI<br />\n#kementerianperindustrian<br />\n#sosialisasiTvet4.0<br />\n#sosialisasiPerkin</p>\n', '<p>Pada tanggal  26 &#8211; 28 Februari 2024, Politeknik STMI Jakarta menggelar Rapat Kerja Tahunan yang menjadi ajang strategis bagi seluruh pimpinan unit, dosen, dan staf untuk merumuskan arah kebijakan dan program kerja yang akan dilaksanakan di tahun mendatang. Rapat kerja…</p>\n', '1', '2397', 'publish', '2024-03-01 10:50:01', '2024-09-05 16:11:11', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2403', 'pengumuman-pengambilan-ktm-mahasiswa-baru-tahun-akademik-2024-2025', 'Pengumuman Pengambilan KTM Mahasiswa Baru Tahun Akademik 2024-2025', '<p>Kepada mahasiswa/i Politeknik STMI Jakarta</p>\n<p>Berikut dibawah ini terlampir Pengumuman Pengambilan KTM Mahasiswa Baru Tahun Akademik 2024-2025</p>\n<p>Mohon untuk dibaca dengan seksama, Terimakasih</p>\n<p>&nbsp;</p>\n<a href=\"{base_url}wp-content/uploads/2024/09/2024-Nomor-3236-Pengumuman-Pengambilan-KTM-Mahasiswa-Baru-Tahun-Akademik-2024-2025.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">2024 Nomor 3236 Pengumuman Pengambilan KTM Mahasiswa Baru Tahun Akademik 2024-2025</a>\n', '<p>Kepada mahasiswa/i Politeknik STMI Jakarta Berikut dibawah ini terlampir Pengumuman Pengambilan KTM Mahasiswa Baru Tahun Akademik 2024-2025 Mohon untuk dibaca dengan seksama, Terimakasih &nbsp;</p>\n', '2', '2377', 'publish', '2024-09-05 13:46:02', '2024-09-05 13:46:02', NULL, NULL);
