INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2459', 'batas-waktu-pembayaran-semester-ganjil-2024-dan-nomor-rekening-baru-politeknik-stmi-jakarta', 'BATAS WAKTU PEMBAYARAN SEMESTER GANJIL 2024 DAN NOMOR REKENING BARU POLITEKNIK STMI JAKARTA', '<p>Menunjuk Pengumuman Direktur Nomor : B/2285/BPSDMI/STMI/PP/VII/2024 tanggal 13 Juli 2024 tentang Awal Semester Ganjil Tahun Akademik 2024/2025 dan Pengumuman Direktur Nomor : B/3051/BPSDMI/STMI/PP/VIII/2024 tanggal 22 Agustus 2024 tentang Perubahan Jadwal Pembayaran SPP / Sidang / Cuti Akademik / Uji Kompetensi dan Proses Perubahan Nomor Rekening Politeknik STMI Jakarta, maka diberitahukan kepada seluruh mahasiswa Politeknik STMI Jakarta sebagai<br />\nberikut:</p>\n<ol>\n<li style=\"list-style-type: none;\">\n<ol>\n<li>Batas waktu pembayaran BPP Semester Ganjil Tahun Akademik 2024/2025 adalah 11 Oktober 2024.</li>\n<li>Seluruh pembayaran biaya pendidikan dilakukan ke Nomor Rekening Baru Politeknik STMI Jakarta, yaitu:<br />\n<strong>Nama Bank : Bank Mandiri</strong><br />\n<strong>Atas Nama : RPL 182 BLU POLTEK STMI UTK OPS PNM</strong><br />\n<strong>No Rekening : 1230012157626</strong></li>\n</ol>\n</li>\n</ol>\n<p>Demikian informasi ini disampaikan agar dapat dilaksanakan sebagaimana mestinya.</p>\n<a href=\"{base_url}wp-content/uploads/2024/10/Nomor-Surat-3627.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">Nomor Surat 3627</a>\n', '<p>Menunjuk Pengumuman Direktur Nomor : B/2285/BPSDMI/STMI/PP/VII/2024 tanggal 13 Juli 2024 tentang Awal Semester Ganjil Tahun Akademik 2024/2025 dan Pengumuman Direktur Nomor : B/3051/BPSDMI/STMI/PP/VIII/2024 tanggal 22 Agustus 2024 tentang Perubahan Jadwal Pembayaran SPP / Sidang / Cuti Akademik / Uji Kompetensi…</p>\n', '1', '2377', 'publish', '2024-10-03 14:43:38', '2024-10-03 14:44:26', NULL, NULL);
