INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2504', 'jadwal-ujian-tengah-semester-ganjil-tahun-akademik-2024-2025', 'Jadwal Ujian Tengah Semester Ganjil Tahun Akademik 2024 / 2025', '<p>Kepada Yth, Bapak/ibu dosen dan mahasiswa Politeknik STMI Jakarta</p>\n<p>Berikut dibawah ini terlampir Jadwal Ujian Tengah Semester Ganjil Tahun Akademik 2024 / 2025</p>\n<p>Terimakasih</p>\n<p>&nbsp;</p>\n<a href=\"{base_url}wp-content/uploads/2024/10/2024-Jadwal-UTS-Ganjil-TA-24-25.pdf\" class=\"pdfemb-viewer\" style=\"\" data-width=\"max\" data-height=\"max\" data-toolbar=\"both\" data-toolbar-fixed=\"on\">2024 Jadwal UTS Ganjil TA 24-25</a>\n<p>&nbsp;</p>\n', '<p>Kepada Yth, Bapak/ibu dosen dan mahasiswa Politeknik STMI Jakarta Berikut dibawah ini terlampir Jadwal Ujian Tengah Semester Ganjil Tahun Akademik 2024 / 2025 Terimakasih &nbsp; &nbsp;</p>\n', '2', '2377', 'publish', '2024-10-16 09:11:46', '2024-10-16 09:11:46', NULL, NULL);
INSERT INTO `posts` (`id`, `slug`, `title`, `content`, `excerpt`, `author_id`, `featured_media_id`, `status`, `published_at`, `modified_at`, `layout_head`, `layout_foot`) VALUES ('2506', 'penjajakan-kerjasama-tvet-oleh-sunmaker-training-institute-ciic-international-education-technology-china', 'Penjajakan Kerjasama TVET oleh Sunmaker Training Institute & CIIC International Education Technology China', '<p><img fetchpriority=\"high\" fetchpriority=\"high\" decoding=\"async\" class=\"size-medium wp-image-2507 aligncenter\" src=\"{base_url}wp-content/uploads/2024/10/1-240x300.jpg\" alt=\"\" width=\"240\" height=\"300\" srcset=\"{base_url}wp-content/uploads/2024/10/1-240x300.jpg 240w, {base_url}wp-content/uploads/2024/10/1-819x1024.jpg 819w, {base_url}wp-content/uploads/2024/10/1-768x960.jpg 768w, {base_url}wp-content/uploads/2024/10/1.jpg 1024w\" sizes=\"(max-width: 240px) 100vw, 240px\" /></p>\n<p>Halo Sobat STMI!</p>\n<p>Pada hari ini, 22 Oktober 2024 telah dilaksanakan Penjajakan Kerjasama TVET oleh Sunmaker Training Institute &amp; CIIC International Education Technology China terkait bidang pendidikan</p>\n<p>Semoga ini menjadi awal kolaborasi yang baik antar kedua nya</p>\n<p><img decoding=\"async\" class=\"alignnone size-medium wp-image-2508\" src=\"{base_url}wp-content/uploads/2024/10/2-240x300.jpg\" alt=\"\" width=\"240\" height=\"300\" srcset=\"{base_url}wp-content/uploads/2024/10/2-240x300.jpg 240w, {base_url}wp-content/uploads/2024/10/2-819x1024.jpg 819w, {base_url}wp-content/uploads/2024/10/2-768x960.jpg 768w, {base_url}wp-content/uploads/2024/10/2.jpg 1024w\" sizes=\"(max-width: 240px) 100vw, 240px\" /> <img decoding=\"async\" class=\"alignnone size-medium wp-image-2511\" src=\"{base_url}wp-content/uploads/2024/10/5-240x300.jpg\" alt=\"\" width=\"240\" height=\"300\" srcset=\"{base_url}wp-content/uploads/2024/10/5-240x300.jpg 240w, {base_url}wp-content/uploads/2024/10/5-819x1024.jpg 819w, {base_url}wp-content/uploads/2024/10/5-768x960.jpg 768w, {base_url}wp-content/uploads/2024/10/5.jpg 1024w\" sizes=\"(max-width: 240px) 100vw, 240px\" /> <img loading=\"lazy\" loading=\"lazy\" decoding=\"async\" class=\"alignnone size-medium wp-image-2512\" src=\"{base_url}wp-content/uploads/2024/10/6-240x300.jpg\" alt=\"\" width=\"240\" height=\"300\" srcset=\"{base_url}wp-content/uploads/2024/10/6-240x300.jpg 240w, {base_url}wp-content/uploads/2024/10/6-819x1024.jpg 819w, {base_url}wp-content/uploads/2024/10/6-768x960.jpg 768w, {base_url}wp-content/uploads/2024/10/6.jpg 1024w\" sizes=\"(max-width: 240px) 100vw, 240px\" /></p>\n<p>&#8212;&#8212;&#8212;&#8212;&#8212;&#8212;&#8212;&#8212;&#8211;</p>\n<p>Join us 📲</p>\n<p>Website : www.stmi.ac.id</p>\n<p>IG: @stmijakarta</p>\n<p>Twitter: @stmijakarta</p>\n<p>Facebook: Politeknik STMI Jakarta</p>\n<p>WA : 085155244455</p>\n<p>&#8212;&#8212;&#8212;&#8212;&#8212;&#8212;&#8212;&#8212;&#8211;</p>\n<p>Kementerian Perindustrian RI</p>\n<p>#politeknikstmijakarta</p>\n<p>#Politeknik</p>\n<p>#STMIJakarta</p>\n<p>#STMIWBK</p>\n<p>#STMIMenujuWBBM</p>\n<p>#Kampus</p>\n<p>#VokasiKompeten</p>\n<p>#SobatIndustri</p>\n<p>#JoinSTMI</p>\n<p>#kementerianperindustrian</p>\n<p>#kerjasama</p>\n<p>&nbsp;</p>\n', '<p>Halo Sobat STMI! Pada hari ini, 22 Oktober 2024 telah dilaksanakan Penjajakan Kerjasama TVET oleh Sunmaker Training Institute &amp; CIIC International Education Technology China terkait bidang pendidikan Semoga ini menjadi awal kolaborasi yang baik antar kedua nya &#8212;&#8212;&#8212;&#8212;&#8212;&#8212;&#8212;&#8212;&#8211; Join us…</p>\n', '2', '2507', 'publish', '2024-10-23 08:25:59', '2024-10-23 08:29:12', NULL, NULL);
