INSERT INTO `pages` (`id`, `slug`, `title`, `content`, `view`, `template`, `author_id`, `featured_media_id`, `status`, `layout_head`, `layout_foot`, `published_at`, `modified_at`) VALUES ('811', 'profile-pejabat', 'Profile Pejabat', '\n					<div data-elementor-type=\"wp-page\" data-elementor-id=\"811\" class=\"elementor elementor-811\">\n				<div class=\"elementor-element elementor-element-322e1ccb e-flex e-con-boxed e-con e-parent\" data-id=\"322e1ccb\" data-element_type=\"container\">\n					<div class=\"e-con-inner\">\n				<div class=\"elementor-element elementor-element-3cf5419a elementor-widget elementor-widget-text-editor\" data-id=\"3cf5419a\" data-element_type=\"widget\" data-widget_type=\"text-editor.default\">\n				<div class=\"elementor-widget-container\">\n									<p><strong>Profil Pejabat Politeknik STMI Jakarta sebagai berikut:</strong></p><ul><li>Direktur : Amrin Rapi, ST, MT<br />S1 : Universitas Hassanudin jurusan Teknik Mesin<br />S2 : Institut Teknologi Bandung jurusan Teknik dan Manajemen Industri</li><li> </li><li>Pembantu Direktur I : Fitria Ika Aryanti, S.T., M.Eng<br />S1 : Universitas Pembangunan Nasional Veteran, Yogyakarta Jurusan Teknik Kimia<br />S2 : Universitas Gadjah Mada, Yogyakarta Jurusan Teknik Kimia</li><li> </li></ul><ul><li>Pembantu Direktur II : Ahlan Ismono, S.Kom, MMSI<br />S1 : Institut Sains dan Teknologi Al-Kamal Jurusan Teknik Informatika<br />S2 : Universitas Gunadarma Jurusan Manajemen Sistem Informasi</li><li> </li></ul><ul><li>Pembantu Direktur III : Lucyana Tresia, MT<br />S1 : Universitas Sriwijaya jurusan Kimia<br />S2 : Universitas Indonesia jurusan Teknik Industri</li><li> </li></ul><ul><li>Ketua Senat : Indah Kurnia Mahasih Lianny, ST, MT<br />S1 : Universitas Indonesia Jurusan Teknik Industri<br />S2 : Institut Teknologi Bandung Jurusan Teknik dan Manajemen Industri</li><li> </li></ul><ul><li>Ketua Jurusan/Program Studi Teknik Industri Otomotif : Dianasanti Salati, MT<br />S1 : Institut Teknologi Bandung jurusan Teknik Material<br />S2 : Institut Teknologi Bandung jurusan Teknik dan Manajemen Industri</li><li> </li></ul><ul><li>Ketua Jurusan/Program Studi Sistem Informasi Industri Otomotif : Gita Mustika Rahmah, M.T<br />S1 : Universitas Putra Indonesia &#8216;YPTK&#8217; Jurusan Sistem Informasi<br />S2 : Institut Teknologi Bandung Jurusan Sistem Informasi</li><li> </li></ul><ul><li>Ketua Jurusan/Program Studi Administrasi Bisnis Otomotif : Fitra Aprilindo Sase, MM<br />S1 : Universitas Diponegoro Jurusan Ilmu Gizi<br />S2 : Universitas Diponegoro Jurusan Manajemen</li><li> </li></ul><ul><li>Ketua Jurusan/Program Studi Teknik Kimia Polimer : Reviana Inda Dwi Suyatmo, M.Eng<br />S1 : Universitas Gadjah Mada Jurusan Teknik Kimia<br />S2 : Universitas Gadjah Mada Jurusan Teknik Kimia</li><li> </li></ul><ul><li>Kepala Unit Teaching Factory : Muhamad Agus, ST.MT<br />S1 : Institut Sains dan Teknologi Nasional Jurusan Teknik Mesin<br />S2 : Institut Sains dan Teknologi Nasional ( ISTN) Jurusan Teknik Mesin</li><li> </li></ul><ul><li>Kepala Unit Inkubator Bisnis : Irma Agustiningsih Imdam, S.ST, MT<br />S1 : Sekolah Tinggi Manajemen Industri Jurusan Manajemen Industri<br />S2 : Universitas Trisakti Jurusan Teknik Industri</li><li> </li></ul><ul><li>Kepala Unit Penelitian dan Pengabdian Masyarakat : Muchamad Taufiq Anwar, M.Kom<br />S1 : Universitas Kristen Satya Wacana Jurusan Pendidikan Teknik Informatika dan Komputer<br />S2 : Universitas Kristen Satya Wacana Jurusan Magister Sistem Informasi</li><li> </li></ul><ul><li>Kepala Unit Transformasi 4.0: Febry P J Sibuea, S.Kom., MMSI.<br />S1 : Universitas Bina Nusantara Jurusan Sistem Informasi<br />S2 : Universitas Bina Nusantara Jurusan Manajemen Sistem Informasi</li><li> </li></ul><ul><li>Kepala Satuan Penjaminan Mutu : Ella Melyna, M.T<br />S1 : Universitas Riau Jurusan TTeknik Kimia<br />S2 : Institut Teknologi Bandung Jurusan Teknik Kimia</li><li> </li></ul><ul><li>Kepala Satuan Pengawas Internal : Angelia Merdiyanti, S.TP, MM<br />S1 : Institut Pertanian Bogor Jurusan Teknologi Pangan<br />S2 : Institut Pertanian Bogor Jurusan Manajemen dan Bisnis</li><li> </li></ul><ul><li>Kepala Subbagian Adm. Akademik, Kemahasiswaan &amp; Kerja Sama : Samsudin, ST<br />S1 : Universitas Pamulang Jurusan Teknik Mesin</li><li> </li></ul><ul><li>Kepala Subbagian Umum dan Keuangan : Choiriah, SE<br />S1 : Sekolah Tinggi Ilmu Ekonomi YKPN Jurusan Ekonomi</li></ul>								</div>\n				</div>\n					</div>\n				</div>\n				</div>\n				', NULL, 'default', '1', NULL, 'publish', 'profile-pejabat', 'profile-pejabat', '2024-03-10 06:25:54', '2025-02-10 15:33:18');
