INSERT INTO `pages` (`id`, `slug`, `title`, `content`, `view`, `template`, `author_id`, `featured_media_id`, `status`, `layout_head`, `layout_foot`, `published_at`, `modified_at`) VALUES ('975', 'hasil-indeks-persepsi-korupsi', 'Hasil Indeks Persepsi Korupsi', '\n					<div data-elementor-type=\"wp-page\" data-elementor-id=\"975\" class=\"elementor elementor-975\">\n				<div class=\"elementor-element elementor-element-5486ade8 e-flex e-con-boxed e-con e-parent\" data-id=\"5486ade8\" data-element_type=\"container\">\n					<div class=\"e-con-inner\">\n				<div class=\"elementor-element elementor-element-313b73dc elementor-widget elementor-widget-text-editor\" data-id=\"313b73dc\" data-element_type=\"widget\" data-widget_type=\"text-editor.default\">\n				<div class=\"elementor-widget-container\">\n									<p>Berikut Hasil Survey Indeks Persepsi Korupsi berdasarkan Kuesioner Periode Januari &#8211; Maret 2026</p><table border=\"0\" width=\"100%\" cellspacing=\"1\" cellpadding=\"4\"><tbody><tr><td align=\"center\"><strong>No.</strong></td><td align=\"center\"><strong>Pertanyaan</strong></td><td align=\"center\"><strong>Nilai</strong></td></tr><tr><td align=\"center\">1</td><td>Prosedur pelayanan yang ditetapkan sudah memadai dan tidak berpotensi menimbulkan korupsi, kolusi dan nepotisme (KKN)</td><td align=\"center\">3.8631</td></tr><tr><td align=\"center\">2</td><td>Petugas pelayanan tidak memberikan pelayanan di luar prosedur yang telah ditetapkan dengan imbalan uang/barang</td><td align=\"center\">3.5221</td></tr><tr><td align=\"center\">3</td><td>Tidak terdapat praktek pen-calo-an/perantara yang tidak resmi</td><td align=\"center\">3.999</td></tr><tr><td align=\"center\">4</td><td>Petugas pelayanan tidak diskriminatif</td><td align=\"center\">3.8425</td></tr><tr><td align=\"center\">5</td><td>Tidak terdapat pungutan liar dalam pelayanan</td><td align=\"center\">3.9312</td></tr><tr><td align=\"center\">6</td><td>Petugas pelayanan tidak meminta/menuntut imbalan uang/barang terkait pelayanan yang diberikan</td><td align=\"center\">3.7993</td></tr><tr><td align=\"center\">7</td><td>Petugas pelayanan menolak pemberian uang/barang terkait pelayanan yang diberikan</td><td align=\"center\">3.8678</td></tr><tr><td align=\"center\">8</td><td>Produk/jasa layanan yang diterima sesuai dengan daftar produk/jasa layanan yang tersedia/diminta</td><td align=\"center\">3.7996</td></tr><tr><td align=\"center\">9</td><td>Tidak diskriminatif dalam penanganan pengaduan</td><td align=\"center\">3.8251</td></tr><tr><td colspan=\"2\" align=\"center\"><strong>Grand Total</strong></td><td align=\"center\"><strong>3.8278</strong></td></tr></tbody></table>								</div>\n				</div>\n					</div>\n				</div>\n				</div>\n				', NULL, 'default', '1', NULL, 'publish', 'hasil-indeks-persepsi-korupsi', 'hasil-indeks-persepsi-korupsi', '2024-03-10 22:37:53', '2026-04-21 12:51:37');
