INSERT INTO `pages` (`id`, `slug`, `title`, `content`, `view`, `template`, `author_id`, `featured_media_id`, `status`, `layout_head`, `layout_foot`, `published_at`, `modified_at`) VALUES ('997', 'peraturan', 'Peraturan', '\n			[wpdm_package id=\'1172\']\n[wpdm_package id=\'1188\']\n[wpdm_package id=\'1189\']\n[wpdm_package id=\'1190\']\n[wpdm_package id=\'1191\']\n[wpdm_package id=\'1192\']\n[wpdm_package id=\'1194\']\n[wpdm_package id=\'1205\']\n		', NULL, 'default', '1', NULL, 'publish', 'peraturan', 'daftar-isian-penggunaan-anggaran', '2024-03-10 22:54:46', '2024-09-09 12:57:56');
INSERT INTO `pages` (`id`, `slug`, `title`, `content`, `view`, `template`, `author_id`, `featured_media_id`, `status`, `layout_head`, `layout_foot`, `published_at`, `modified_at`) VALUES ('999', 'zona-integritas', 'Zona Integritas', '\n			<p>Reformasi birokrasi merupakan salah satu langkah awal untuk melakukan penataan terhadap sistem penyelenggaraan pemerintahan yang baik, efektif dan efisien, sehingga dapat melayani masyarakat secara cepat, tepat, dan profesional. Dalam perjalanannya, banyak kendala yang dihadapi, diantaranya adalah penyalahgunaan wewenang, praktek KKN, dan lemahnya pengawasan.</p>\n<p>Sejalan dengan hal tersebut, Pemerintah telah menerbitkan Peraturan Presiden Nomor 81 Tahun 2010 Tentang Grand Design Reformasi Birokrasi yang mengatur tentang pelaksanaan program reformasi birokrasi. Peraturan tersebut menargetkan tercapainya tiga sasaran hasil utama yaitu peningkatan kapasitas dan akuntabilitas organisasi, pemerintah yang bersih dan bebas KKN, serta peningkatan pelayanan publik.</p>\n<p>Dalam rangka mengakselerasi pencapaian sasaran hasil tersebut, maka instansi pemerintah (pusat dan daerah) perlu untuk membangun <em>pilot project</em> pelaksanaan reformasi birokrasi yang dapat menjadi percontohan penerapan pada unit-unit kerja lainnya. Untuk itu, perlu secara konkret dilaksanakan program reformasi birokrasi pada unit kerja melalui upaya <strong>pembangunan Zona Integritas</strong>.</p>\n<p>“Zona Integritas (ZI) adalah predikat yang diberikan kepada instansi pemerintah yang pimpinan dan jajarannya mempunyai komitmen untuk mewujudkan Wilayah Bebas dari Korupsi (WBK)/Wilayah Birokrasi Bersih dan Melayani (WBBM) melalui reformasi birokrasi, khususnya dalam hal pencegahan korupsi dan peningkatan kualitas pelayanan publik”. (<a href=\"{base_url}assets/uploads/peraturan/Permenpan_No.52_2014_.html\">Permenpan No 52 Tahun 2014</a>)</p>\n<p>Zona Integritas (ZI) merupakan sebutan atau predikat yang diberikan kepada K/L dan Pemda yang pimpinan dan jajarannya mempunyai niat (komitmen) untuk mewujudkan WBK dan WBBM melalui upaya pencegahan korupsi, reformasi birokrasi dan peningkatan kualitas pelayanan publik. K/L dan Pemda yang telah mencanangkan sebagai ZI mengusulkan salah satu unit kerjanya untuk menjadi Wilayah Bebas dari Korupsi.</p>\n<p><strong>Wilayah Bebas dari Korupsi</strong> (WBK) adalah predikat yang diberikan kepada suatu unit kerja yang memenuhi sebagian besar manajemen perubahan, penataan tatalaksana, penataan sistem manajemen SDM, penguatan pengawasan, dan penguatan akuntabilitas kinerja. Sedangkan <strong>Wilayah Birokrasi Bersih dan Melayani</strong> (WBBM) adalah predikat yang diberikan kepada suatu unit kerja yang memenuhi sebagian besar manajemen perubahan, penataan tatalaksana, penataan sistem manajemen SDM, penguatan pengawasan, penguatan akuntabilitas kinerja, dan penguatan kualitas pelayanan publik.</p>\n<p>Diharapkan melalui pembangunan zona integritas ini unit kerja yang telah menjadi WBK/WBBM dapat menjadi <em>pilot project</em> dan <em>benchmark</em> untuk unit kerja lainnya sehingga seluruh unit kerja tersebut diberikan kebebasan untuk bekerja dengan benar sesuai dengan ketentuan perundangan-undangan. Selain itu Unit kerja berpredikat WBK/WBBM merupakan <em>outcome</em> dari upaya pencegahan korupsi yang dilaksanakan secara konkrit di dalam lingkup Zona Integritas.</p>\n<blockquote><p><span style=\"color: red;\"><strong><a href=\"http://ppid.stmi.ac.id/\">Masuk ke Website Pejabat Pengelola Informasi dan Dokumentasi (PPID) Politeknik STMI Jakarta</a></strong></span></p></blockquote>\n		', NULL, 'default', '1', NULL, 'publish', 'sejarah-kampus', 'akademik', '2024-03-10 22:56:54', '2024-03-10 22:57:26');
